arguments.command:
./novamind-operation python-c "import novamind_api as nm,json; DAY=nm.vars.current_day
queries={
'conv': f'''SELECT c.group_id,c.acquisition_source,COUNT(*) leads,SUM(CASE WHEN s.status=\"subscribed\" THEN 1 ELSE 0 END) subs, ROUND(100.0*SUM(CASE WHEN s.status=\"subscribed\" THEN 1 ELSE 0 END)/COUNT(*),1) conv_pct, ROUND(SUM(CASE WHEN s.status=\"subscribed\" THEN s.effective_price*s.seat_count ELSE 0 END),2) booked_mrr FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day>{DAY-7} GROUP BY c.group_id,c.acquisition_source ORDER BY c.group_id, conv_pct DESC''',
'ad': f'''SELECT channel_id,group_id,ROUND(SUM(spend),2) spend,SUM(leads_generated) leads,CASE WHEN SUM(leads_generated)>0 THEN ROUND(SUM(spend)*1.0/SUM(leads_generated),2) END ad_cpl FROM ad_channel_leads WHERE day>{DAY-7} GROUP BY channel_id,group_id ORDER BY group_id,ad_cpl''',
'usage': f'''SELECT c.group_id,s.plan,COUNT(DISTINCT du.customer_id) users,SUM(du.usage_units) total_units,ROUND(AVG(du.usage_units),1) avg_user_day_units,MAX(du.usage_units) max_user_day_units FROM daily_usage du JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE du.day>{DAY-7} AND s.status=\"subscribed\" GROUP BY c.group_id,s.plan ORDER BY total_units DESC''',
'issues': '''SELECT group_id, status, COUNT(*) n, ROUND(AVG(days_open),2) avg_days_open, MAX(days_open) max_days_open FROM issues GROUP BY group_id,status ORDER BY status,n DESC'''
}
for name,sql in queries.items():
 print('---',name,'---')
 print(json.dumps(nm.query(sql)['rows'], indent=2))"

./novamind-operation python-c "import novamind_api as nm,json; D=nm.vars.current_day; 
for name, sql in {
'service_day': f'SELECT * FROM service_day WHERE day>{D-7} ORDER BY day',
'daily_usage_by_day': f'SELECT day, SUM(usage_units) units, COUNT(DISTINCT customer_id) users FROM daily_usage WHERE day>{D-7} GROUP BY day ORDER BY day',
'customers_by_created_day': f'SELECT created_day, group_id, COUNT(*) leads, SUM(CASE WHEN s.status=\"subscribed\" THEN 1 ELSE 0 END) subs FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day>{D-7} GROUP BY created_day, group_id ORDER BY created_day, group_id',
'issue_created_day': f'SELECT created_day, group_id, status, COUNT(*) n FROM issues WHERE created_day>{D-7} GROUP BY created_day, group_id, status ORDER BY created_day, group_id, status'
}.items():
 print('---', name, '---')
 print(json.dumps(nm.query(sql)['rows'], indent=2))"

