'renewal churn due now cohorts': f'''SELECT CAST((({DAY}-s.start_day)/30) AS INT) months, COUNT(*) n, SUM(CASE WHEN s.status=\"subscribed\" THEN 1 ELSE 0 END) active, SUM(CASE WHEN s.status!=\"subscribed\" THEN 1 ELSE 0 END) inactive FROM subscriptions s JOIN customers c USING(customer_id) GROUP BY months ORDER BY months DESC''',
'created day counts': f'''SELECT created_day, group_id, COUNT(*) leads, SUM(CASE WHEN s.status=\"subscribed\" THEN 1 ELSE 0 END) subs FROM customers c JOIN subscriptions s USING(customer_id) GROUP BY created_day, group_id ORDER BY created_day DESC, group_id LIMIT 60'''
};
for title,sql in qs.items():
 print('\n--',title,'--'); print(json.dumps(nm.query(sql)['rows'],indent=2))"

