'retention by start_week': f'''SELECT (s.start_day/7) start_week, c.group_id,s.plan, COUNT(*) total, SUM(CASE WHEN s.status=\"subscribed\" THEN 1 ELSE 0 END) active, SUM(CASE WHEN s.status=\"cancelled\" THEN 1 ELSE 0 END) cancelled, SUM(CASE WHEN s.status=\"lost\" THEN 1 ELSE 0 END) lost FROM subscriptions s JOIN customers c USING(customer_id) GROUP BY start_week,c.group_id,s.plan ORDER BY start_week,c.group_id,s.plan'''
};
for title,sql in queries.items():
 print('\n--',title,'--'); print(json.dumps(nm.query(sql)['rows'],indent=2)[:12000])"

