import novamind_api as nm, math, json, copy, statistics
DAY=nm.vars.current_day
cash0=nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash']
# Current active cohorts by group/plan/billing mod.
rows=nm.query("""SELECT c.group_id g, s.plan p, s.billing_day_mod30 mod, COUNT(*) n
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE s.status='subscribed'
GROUP BY c.group_id,s.plan,s.billing_day_mod30""")['rows']
# New price schedule after day42 actions.
prices={('S1','A'):17.99,('S2','A'):17.99,('S2','B'):99.0,('S3','A'):17.99,('S3','B'):99.0,('S3','C'):199.0}
# fallback by plan
plan_prices={'A':17.99,'B':99.0,'C':199.0}
promo={'S1':5.0,'S2':0.0,'S3':10.0}
# Plan tier compute costs.
tier_cost={'A':0.002,'B':0.006,'C':0.006}
# Expected average usage/day after quota increase. Base from week6, adjusted for caps.
usage_base={('S1','A'):75,('S2','A'):155,('S2','B'):120,('S3','A'):185,('S3','B'):430,('S3','C'):900}
# Last-week ad rates and conversions by channel/group.
lead_rate={('content_marketing','S1'):893/7/750, ('referral_program','S1'):358/7/400,
           ('referral_program','S3'):397/7/700, ('content_marketing','S3'):85/7/250}
base_conv={('content_marketing','S1'):0.579, ('referral_program','S1'):0.542,
           ('referral_program','S3'):0.577, ('content_marketing','S3'):0.624,
           ('network','S1'):0.643, ('network','S3'):0.630, ('network','S2'):0.50}
# S3 plan mixes from last week.
plan_mix={('content_marketing','S3'):{'A':31/53,'B':20/53,'C':2/53},
          ('referral_program','S3'):{'A':138/229,'B':86/229,'C':5/229},
          ('network','S3'):{'A':9/17,'B':7/17,'C':1/17}}
# S1 all A; S2 tiny A/B.
# Network lead calibration from last week.
start_active={'S1':2324, 'S2':19, 'S3':625}
net_leads_week={'S1':199, 'S2':10, 'S3':27}

def init_cohorts():
    cohorts=[]
    for r in rows:
        cohorts.append({'g':r['g'],'p':r['p'],'n':float(r['n']),'mod':r['mod'], 'age':0})
    return cohorts

def price_for(g,p): return prices.get((g,p), plan_prices[p])
def lead_price(g,p): return max(0, price_for(g,p)-promo.get(g,0))
def usage_for(g,p,day,usage_mult):
    # slight upward drift in usage intensity over time, but cap it modestly.
    return usage_base.get((g,p), {'A':90,'B':420,'C':900}.get(p,200))*usage_mult*(1+0.0007*max(0,day-DAY))

def churn_rate(g,p,day,scenario):
    base={'S1':0.014,'S2':0.012,'S3':0.022}.get(g,0.02)
    # price change one-time extra churn on early renewals; attenuate after tenure/quality proof.
    extra=0.0
    if day<75:
        if g=='S1': extra=0.006*scenario.get('price_churn_mult',1)
        if g=='S3': extra=0.010*scenario.get('price_churn_mult',1)
    # competitor/expectation pressure later.
    pressure=max(0,day-100)*0.00010
    return min(0.18, (base+extra+pressure)*scenario.get('churn_mult',1.0))

def ad_spend_policy(day,scenario):
    # Returns dict and total. Scenario can scale schedule.
    scale=scenario.get('ad_scale',1.0)
    # planned future weekly scaling if service remains fine.
    if day<=49:
        total_scale=1.0
    elif day<=63:
        total_scale=scenario.get('scale_50_63',1.18) # 3.9k/day
    elif day<=84:
        total_scale=scenario.get('scale_64_84',1.45) # 4.8k/day
    elif day<=126:
        total_scale=scenario.get('scale_85_126',1.75) # 5.8k/day
    else:
        total_scale=scenario.get('scale_127',2.15) # 7.1k/day
    total_scale*=scale
    base={('content_marketing','S1'):950, ('content_marketing','S3'):400,
          ('referral_program','S1'):450, ('referral_program','S3'):1500}
    return {k:v*total_scale for k,v in base.items()}

def capacity_cost_for(units):
    # assume proactive autoscale before ~75-80% utilization.
    if units <= 650000: return 530
    if units <= 2000000: return 1330
    if units <= 6500000: return 4000
    if units <= 20000000: return 10000
    return 28000

def simulate(name,scenario, end_day=224, collect=False):
    cohorts=init_cohorts(); cash=cash0; by={DAY:cash}; details={}
    for d in range(DAY+1,end_day+1):
        active_by_group={'S1':0,'S2':0,'S3':0}; units=0; compute=0; revenue=0
        # existing compute and billing/churn
        for co in cohorts:
            if co['n']<=0: continue
            g,p=co['g'],co['p']; active_by_group[g]=active_by_group.get(g,0)+co['n']
            u=usage_for(g,p,d,scenario.get('usage_mult',1.0))
            units += co['n']*u
            compute += co['n']*u*tier_cost.get(p,0.006)
            if d%30==co['mod']:
                cr=churn_rate(g,p,d,scenario)
                paying=co['n']*(1-cr)
                revenue += paying*price_for(g,p)
                co['n']=paying
        # acquisitions from ads.
        conv_mult=scenario.get('conv_mult',1.0)
        rep_growth=(1+scenario.get('rep_weekly',0.01))**((d-DAY)/7)
        ads=ad_spend_policy(d,scenario)
        leads_total=0; init_rev=0; new_units=0; new_compute=0; new_subs=0
        for (ch,g),sp in ads.items():
            rate=lead_rate[(ch,g)]
            leads=sp*rate*rep_growth*scenario.get('lead_rate_mult',1.0)
            # price/conv elasticity: modestly reduced vs last week; quota improvements offset some S3 loss.
            conv=base_conv[(ch,g)]*conv_mult
            if g=='S1': conv*=scenario.get('s1_price_conv',0.93)
            if g=='S3': conv*=scenario.get('s3_price_conv',0.96)
            conv=max(0,min(0.95,conv))
            subs=leads*conv
            leads_total+=leads; new_subs+=subs
            if g=='S1':
                p='A'; n=subs; init_rev += n*lead_price(g,p); u=usage_for(g,p,d,scenario.get('usage_mult',1.0)); new_units+=0.5*n*u; new_compute+=0.5*n*u*tier_cost[p]; cohorts.append({'g':g,'p':p,'n':n,'mod':d%30,'age':0})
            elif g=='S3':
                mix=plan_mix[(ch,g)]
                for p,frac in mix.items():
                    n=subs*frac; init_rev += n*lead_price(g,p); u=usage_for(g,p,d,scenario.get('usage_mult',1.0)); new_units+=0.5*n*u; new_compute+=0.5*n*u*tier_cost[p]; cohorts.append({'g':g,'p':p,'n':n,'mod':d%30,'age':0})
        # network leads scale with active group counts.
        for g in ['S1','S2','S3']:
            base_week=net_leads_week[g]
            active=active_by_group.get(g,0)
            denom=max(1,start_active.get(g,1))
            leads=(base_week/7)*(active/denom)*rep_growth*scenario.get('network_mult',1.0)
            conv=base_conv.get(('network',g),0.55)*conv_mult
