# Forecast model with market-cap saturation; copied from forecast_week6 with caps.
import novamind_api as nm, math, json
DAY=nm.vars.current_day
cash0=nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash']
rows=nm.query("""SELECT c.group_id g, s.plan p, s.billing_day_mod30 mod, COUNT(*) n
FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed'
GROUP BY c.group_id,s.plan,s.billing_day_mod30""")['rows']
prices={('S1','A'):17.99,('S2','A'):17.99,('S2','B'):99.0,('S3','A'):17.99,('S3','B'):99.0,('S3','C'):199.0}; plan_prices={'A':17.99,'B':99.0,'C':199.0}; promo={'S1':5.0,'S2':0.0,'S3':10.0}
tier_cost={'A':0.002,'B':0.006,'C':0.006}; usage_base={('S1','A'):75,('S2','A'):155,('S2','B'):120,('S3','A'):185,('S3','B'):430,('S3','C'):900}
lead_rate={('content_marketing','S1'):893/7/750, ('referral_program','S1'):358/7/400, ('referral_program','S3'):397/7/700, ('content_marketing','S3'):85/7/250}
base_conv={('content_marketing','S1'):0.579, ('referral_program','S1'):0.542, ('referral_program','S3'):0.577, ('content_marketing','S3'):0.624, ('network','S1'):0.643, ('network','S3'):0.630, ('network','S2'):0.50}
plan_mix={('content_marketing','S3'):{'A':31/53,'B':20/53,'C':2/53}, ('referral_program','S3'):{'A':138/229,'B':86/229,'C':5/229}, ('network','S3'):{'A':9/17,'B':7/17,'C':1/17}}
start_active={'S1':2324, 'S2':19, 'S3':625}; net_leads_week={'S1':199, 'S2':10, 'S3':27}
cap0={'S1':272812,'S2':167374,'S3':65292}; cap_growth={'S1':0.0962,'S2':0.149,'S3':0.0703}

def price_for(g,p): return prices.get((g,p), plan_prices[p])
def lead_price(g,p): return max(0, price_for(g,p)-promo.get(g,0))
def usage_for(g,p,day,um): return usage_base.get((g,p), {'A':90,'B':420,'C':900}.get(p,200))*um*(1+0.0007*max(0,day-DAY))
def market_cap(g,day): return cap0.get(g,100000)*((1+cap_growth.get(g,0.1))**((day-DAY)/365))
def sat_factor(g,active,day):
    # Strong slowdown after 75% cap; still some replacement. Avoid total zero due churn.
    cap=market_cap(g,day); frac=max(0,min(1,active/cap)); return max(0.02,(1-frac)**1.4)
def churn_rate(g,p,day,s):
    base={'S1':0.014,'S2':0.012,'S3':0.022}.get(g,0.02); extra=0
    if day<75:
        if g=='S1': extra=0.006*s.get('price_churn_mult',1)
        if g=='S3': extra=0.010*s.get('price_churn_mult',1)
    pressure=max(0,day-100)*0.00010
    return min(0.18,(base+extra+pressure)*s.get('churn_mult',1.0))
def ad_spend_policy(day,s):
    if day<=49: total_scale=1.0
    elif day<=63: total_scale=s.get('scale_50_63',1.18)
    elif day<=84: total_scale=s.get('scale_64_84',1.45)
    elif day<=126: total_scale=s.get('scale_85_126',1.75)
    else: total_scale=s.get('scale_127',2.15)
    total_scale*=s.get('ad_scale',1.0)
    base={('content_marketing','S1'):950,('content_marketing','S3'):400,('referral_program','S1'):450,('referral_program','S3'):1500}
    return {k:v*total_scale for k,v in base.items()}
def cap_cost(units):
    if units<=650000: return 530
    if units<=2000000: return 1330
    if units<=6500000: return 4000
    if units<=20000000: return 10000
    if units<=65000000: return 28000
    return 75000

def simulate(name,s,end=224):
    cohorts=[{'g':r['g'],'p':r['p'],'n':float(r['n']),'mod':r['mod']} for r in rows]
    cash=cash0; by={DAY:cash}; details={}
    for d in range(DAY+1,end+1):
        active_by={}
        for co in cohorts: active_by[co['g']]=active_by.get(co['g'],0)+co['n']
        units=0; compute=0; revenue=0
        for co in cohorts:
            if co['n']<=0: continue
            g,p=co['g'],co['p']; u=usage_for(g,p,d,s.get('usage_mult',1.0)); units+=co['n']*u; compute+=co['n']*u*tier_cost.get(p,0.006)
            if d%30==co['mod']:
                paying=co['n']*(1-churn_rate(g,p,d,s)); revenue+=paying*price_for(g,p); co['n']=paying
        conv_mult=s.get('conv_mult',1.0); rep=(1+s.get('rep_weekly',0.01))**((d-DAY)/7)
        leads_total=0; init_rev=0; new_units=0; new_compute=0; new_subs=0
        ads=ad_spend_policy(d,s)
        def add_new(g,p,n):
            nonlocal init_rev,new_units,new_compute
            if n<=0: return
            init_rev += n*lead_price(g,p); u=usage_for(g,p,d,s.get('usage_mult',1.0)); new_units += 0.5*n*u; new_compute += 0.5*n*u*tier_cost.get(p,0.006); cohorts.append({'g':g,'p':p,'n':n,'mod':d%30})
        for (ch,g),sp in ads.items():
            sat=sat_factor(g,active_by.get(g,0),d)
            leads=sp*lead_rate[(ch,g)]*rep*s.get('lead_rate_mult',1.0)*sat
            conv=base_conv[(ch,g)]*conv_mult*(s.get('s1_price_conv',0.93) if g=='S1' else s.get('s3_price_conv',0.96))
            subs=leads*max(0,min(0.95,conv)); leads_total+=leads; new_subs+=subs
            if g=='S1': add_new(g,'A',subs)
            elif g=='S3':
                for p,frac in plan_mix[(ch,g)].items(): add_new(g,p,subs*frac)
        for g in ['S1','S2','S3']:
            sat=sat_factor(g,active_by.get(g,0),d)
            leads=(net_leads_week[g]/7)*(active_by.get(g,0)/max(1,start_active[g]))*rep*s.get('network_mult',1.0)*sat
            conv=base_conv.get(('network',g),0.55)*conv_mult*(s.get('s1_price_conv',0.93) if g=='S1' else s.get('s3_price_conv',0.96) if g=='S3' else 1.0)
            subs=leads*conv; leads_total+=leads; new_subs+=subs
            if g=='S1': add_new(g,'A',subs)
            elif g=='S3':
                for p,frac in plan_mix[('network','S3')].items(): add_new(g,p,subs*frac)
            else:
                add_new(g,'A',subs*0.8); add_new(g,'B',subs*0.2)
        units+=new_units; compute+=new_compute
        ad_total=sum(ads.values()); ops=1800 if d<=70 else s.get('ops_later',1500); dev=s.get('dev',1000); cap=cap_cost(units); lead_cost=0.5*leads_total
        cash += revenue+init_rev-(ad_total+ops+dev+cap+lead_cost+compute); by[d]=cash
        if d in [49,70,126,224]:
            active_by2={}
            for co in cohorts: active_by2[co['g']]=active_by2.get(co['g'],0)+co['n']
            details[d]={'cash':cash,'active':sum(active_by2.values()),'active_by':active_by2,'mrr':sum(co['n']*price_for(co['g'],co['p']) for co in cohorts),'units':units,'compute':compute,'revenue':revenue,'init_rev':init_rev,'ads':ad_total,'cap':cap,'leads':leads_total,'new_subs':new_subs}
    print(name, {h:round(by[h]) for h in [49,70,126,224]})
    print(json.dumps({h:{k:(round(v,1) if isinstance(v,(int,float)) else {kk:round(vv,1) for kk,vv in v.items()}) for k,v in details[h].items()} for h in [49,70,126,224]}, indent=2))

