cat > forecast_adaptive_week7.py <<'PY'
# Adaptive forecast with market caps and weekly ad scaling controls.
import novamind_api as nm, random, math, statistics, json
DAY=nm.vars.current_day
cash0=float(nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash'])
rows=nm.query("""
SELECT c.group_id g, s.plan p, s.billing_day_mod30 mod, ROUND(s.effective_price,2) price, COUNT(*) n
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE s.status='subscribed'
GROUP BY c.group_id,s.plan,s.billing_day_mod30,ROUND(s.effective_price,2)
""")['rows']
new_price={'A':17.99,'B':99.0,'C':199.0}; lead_promo={'S1':5.0,'S2':0,'S3':10.0}; tier_cost={'A':.002,'B':.006,'C':.006}
usage_base={('S1','A'):80,('S2','A'):175,('S2','B'):170,('S3','A'):230,('S3','B'):560,('S3','C'):1100}
lead_rate={('content_marketing','S1'):1043/7/950, ('referral_program','S1'):422/7/450,('referral_program','S3'):841/7/1500, ('content_marketing','S3'):142/7/400}
conv_base={('content_marketing','S1'):481/1043, ('referral_program','S1'):210/422,('referral_program','S3'):498/841, ('content_marketing','S3'):80/142,('network','S1'):110/246, ('network','S2'):7/12, ('network','S3'):37/58}
plan_mix={('content_marketing','S3'):{'A':.60,'B':.40},('referral_program','S3'):{'A':326/498,'B':172/498},('network','S3'):{'A':29/37,'B':8/37}}
cur_active={r['g']:r['n'] for r in nm.query("SELECT c.group_id g, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id")['rows']}
network_week0={'S1':246,'S2':12,'S3':58}
base_alloc={('content_marketing','S1'):1250, ('referral_program','S1'):500, ('referral_program','S3'):2500, ('content_marketing','S3'):750}
base_total=sum(base_alloc.values())
alloc_frac={k:v/base_total for k,v in base_alloc.items()}
# Info-level-1 noisy; use draw multipliers per scenario.
base_caps={'S1':272812,'S2':167374,'S3':65292}

def capacity_cost(units):
    if units<=2200000: return 1330
    if units<=7000000: return 4000
    if units<=22000000: return 10000
    if units<=70000000: return 28000
    return 75000

def run(params, end=231):
    cohorts=[{'g':r['g'],'p':r['p'],'mod':int(r['mod']),'price':float(r['price']),'n':float(r['n'])} for r in rows]
    caps={g:base_caps[g]*params.get('cap_mult',1.0) for g in base_caps}
    cash=cash0; by={DAY:cash}; details={}; ad_total=5000.0
    # random but deterministic per params? no stochastic in this function unless params contains shocks.
    for d in range(DAY+1,end+1):
        # weekly control after committed week: scale with cash and gross margins.
        if d>56 and d%7==1:
            if cash<220000: ad_total=max(2500, ad_total*0.65)
            elif cash<350000: ad_total=max(3000, ad_total*0.82)
            elif cash>850000: ad_total=min(params.get('max_ads',18000), ad_total*1.30)
            elif cash>600000: ad_total=min(params.get('max_ads',18000), ad_total*1.18)
            elif cash>450000: ad_total=min(params.get('max_ads',18000), ad_total*1.08)
            # else hold
        ads={k:ad_total*frac for k,frac in alloc_frac.items()}
        rev=0; units=0; compute=0; active_by={}
        for co in list(cohorts):
            if co['n']<=1e-6: continue
            g,p=co['g'],co['p']; active_by[g]=active_by.get(g,0)+co['n']
            u=usage_base.get((g,p),100)*params.get('usage_mult',1.0)*(1+params.get('usage_drift',0.0003)*(d-DAY))
            units += co['n']*u; compute += co['n']*u*tier_cost[p]
            if d%30==co['mod']:
                churn={'S1':0.012,'S2':0.015,'S3':0.018}.get(g,.02)*params.get('churn_mult',1.0) + max(0,d-110)*params.get('churn_slope',0.0001)
                churn=min(.25,churn)
                keep=co['n']*(1-churn)
                rev += keep*co['price']; co['n']=keep
        rep=(1+params.get('rep_weekly',0.006))**((d-DAY)/7)
        leads_total=0; init_rev=0; new_subs=0
        # market cap factor by target group (based on active before acquisitions)
        def cap_factor(g):
            a=active_by.get(g,0); cap=caps.get(g,1e9)
            return max(0.03, (1 - min(0.98,a/cap))**params.get('cap_elasticity',1.2))
        for (ch,g),sp in ads.items():
            leads=sp*lead_rate[(ch,g)]*params.get('lead_mult',1.0)*rep*cap_factor(g)
            conv=max(0,min(.9,conv_base[(ch,g)]*params.get('conv_mult',1.0)))
            subs=leads*conv
            leads_total+=leads; new_subs+=subs
            mixes={'A':1.0} if g=='S1' else plan_mix[(ch,g)]
            for p,frac in mixes.items():
                n=subs*frac
                if n<=0: continue
                init_rev += n*max(0,new_price[p]-lead_promo.get(g,0))
                u=usage_base.get((g,p),100)*params.get('usage_mult',1.0)*(1+params.get('usage_drift',0.0003)*(d-DAY))
                units += .5*n*u; compute += .5*n*u*tier_cost[p]
                cohorts.append({'g':g,'p':p,'mod':d%30,'price':new_price[p],'n':n})
        for g,basewk in network_week0.items():
            a=active_by.get(g,cur_active.get(g,1)); denom=max(1,cur_active.get(g,1))
            leads=(basewk/7)*(a/denom)**params.get('network_elasticity',1.0)*params.get('network_mult',1.0)*rep*cap_factor(g)
            conv=max(0,min(.9,conv_base.get(('network',g),.55)*params.get('conv_mult',1.0)))
            subs=leads*conv
            leads_total += leads; new_subs += subs
            mixes={'A':1.0} if g=='S1' else (plan_mix[('network','S3')] if g=='S3' else {'A':.8,'B':.2})
            for p,frac in mixes.items():
                n=subs*frac
                if n<=0: continue
                init_rev += n*max(0,new_price[p]-lead_promo.get(g,0))
                u=usage_base.get((g,p),100)*params.get('usage_mult',1.0)*(1+params.get('usage_drift',0.0003)*(d-DAY))
                units += .5*n*u; compute += .5*n*u*tier_cost[p]
                cohorts.append({'g':g,'p':p,'mod':d%30,'price':new_price[p],'n':n})
        ops=2100 if d<=84 else 1800
        dev=1500 if d<=70 else 1000
        cap=capacity_cost(units)
        cash += rev+init_rev - (ad_total+ops+dev+cap+compute+.5*leads_total)
        by[d]=cash
        if d in [56,77,133,231] or d%28==0:
            details[d]={'cash':cash,'active':sum(c['n'] for c in cohorts),'mrr':sum(c['n']*c['price'] for c in cohorts),'units':units,'ads':ad_total,'compute':compute,'rev':rev,'init_rev':init_rev,'new_subs':new_subs,'leads':leads_total,'cap':cap}
    return by,details

scens={
 'bear': {'conv_mult':.80,'lead_mult':.85,'network_mult':.65,'usage_mult':1.18,'churn_mult':2.0,'rep_weekly':-.002,'cap_mult':.7,'max_ads':9000},
 'low': {'conv_mult':.90,'lead_mult':.95,'network_mult':.85,'usage_mult':1.10,'churn_mult':1.4,'rep_weekly':.002,'cap_mult':.9,'max_ads':12000},
 'base': {'conv_mult':.98,'lead_mult':1.0,'network_mult':1.0,'usage_mult':1.0,'churn_mult':1.0,'rep_weekly':.007,'cap_mult':1.0,'max_ads':16000},
 'high': {'conv_mult':1.05,'lead_mult':1.08,'network_mult':1.25,'usage_mult':.95,'churn_mult':.75,'rep_weekly':.014,'cap_mult':1.25,'max_ads':25000},
 'veryhigh': {'conv_mult':1.10,'lead_mult':1.15,'network_mult':1.45,'usage_mult':.90,'churn_mult':.6,'rep_weekly':.020,'cap_mult':1.6,'max_ads':35000},
}
for n,p in scens.items():
    by,det=run(p)
    print('\n',n,{h:round(by[h]) for h in [56,77,133,231]})
    print(json.dumps({h:{k:round(v,1) for k,v in det[h].items()} for h in [56,77,133,231]},indent=2))
