python3 - <<'PY'
cash=515.9
past_renew={1:16,2:21,3:33,4:53,5:73}
active=179
Ls={}
Fs={}
for w in range(1,27):
    # assume new list grows 2%/wk to 120 then flat? no scaling
    Ls[w]=min(78*(1.025**(w-1)),140)
    Fs[w]=Ls[w]*0.9
for w in range(1,27):
    pay=Fs[w]+past_renew.get(w,0)
    for j in range(1,w):
        if (w-j)%4==0:
            pay += Ls[j]*(0.97**((w-j)//4))
    active=active*0.995+Ls[w]
    compute=0.105*active
    # capacity tier by active mrr/use: tier4 until active>2.5M? maybe tier5 fixed70k/wk when >2.5M? (10k/day=70)
    if active<450: cap=9.31
    elif active<2500: cap=28
    else: cap=70
    fixed=35+14.7+12.6+cap+2.5 # no ad scale
    net=pay-(compute+fixed)
    cash+=net
    if w in [4,8,12,16,20,26]: print(w, 'pay',round(pay),'active',round(active),'net',round(net),'cash',round(cash))
PY

