import novamind_api as nm, math, json, statistics
DAY=nm.vars.current_day
cash0=float(nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash'])
# Active cohorts by group/plan/billing mod/price (effective price used only until price reset; for future use current configured price less ongoing promo)
rows=nm.query("""
SELECT c.group_id g, s.plan p, s.billing_day_mod30 mod, ROUND(AVG(s.effective_price),2) avg_eff, COUNT(*) n
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE s.status='subscribed'
GROUP BY c.group_id,s.plan,s.billing_day_mod30
""")['rows']
# New config after actions
price={'A':19.99,'B':99.0,'C':249.0}
lead_promo={'S1':5.0,'S2':0.0,'S3':0.0}
tier_cost={'A':0.002,'B':0.002,'C':0.006}  # B tier lowered to 2
# Measured usage/sub/day last week from analysis, under current quotas. B tier doesn't change units.
usage={('S1','A'):76.2,('S2','A'):158.9,('S3','A'):279.7,('S3','B'):556.2}
# Ad lead rates per $ from last 7d
ad_lead_rate={('content_marketing','S1'):2112/10500, ('referral_program','S3'):1945/21000}
ad_spend={('content_marketing','S1'):1000.0, ('referral_program','S3'):1500.0}
# Conversion current late week and expected after targeted dev/social. Use base; scenarios adjust.
conv_ad={('content_marketing','S1'):0.18, ('referral_program','S3'):0.40}
conv_net={'S1':0.16,'S2':0.16,'S3':0.45}
# Network lead calibration last week; S1 includes network only, S3 network only, S2 network only.
cur_active={r['g']:r['n'] for r in nm.query("SELECT c.group_id g, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id")['rows']}
network_week={'S1':869,'S2':93,'S3':337}
# Plan mix for S3 from last week by source; B price lower/tier lower may change; scenarios adjust.
plan_mix_s3_ad={'A':612/747,'B':135/747}
plan_mix_s3_net={'A':114/140,'B':26/140}

def init_cohorts():
    return [{'g':r['g'],'p':r['p'],'mod':int(r['mod']),'n':float(r['n']),'price':price[r['p']]} for r in rows]

def cap_cost(units, policy):
    if policy=='tier3_after_2w' and current_day_sim>=DAY+14:
        return 1330
    # maintain tier4 unless usage collapses; actions say tier4.
    return 4000

def simulate(sc, end=DAY+182):
    global current_day_sim
    cohorts=init_cohorts(); cash=cash0; by={DAY:cash}; det={}
    for d in range(DAY+1,end+1):
        current_day_sim=d
        revenue=0.0; units=0.0; compute=0.0
        active_by_group={}
        # Existing + prior new cohorts
        new_co=[]
        for co in cohorts:
            if co['n']<=1e-6: continue
            g,p=co['g'],co['p']
            active_by_group[g]=active_by_group.get(g,0.0)+co['n']
            u=usage.get((g,p), 300.0)*sc.get('usage_mult',1.0)*(1+sc.get('usage_drift',0.00025)*max(0,d-DAY))
            units += co['n']*u
            compute += co['n']*u*tier_cost.get(p,0.002)
            if d%30==co['mod']:
                # monthly churn at billing; B tier change can increase B churn in bear scenarios, lower B price mitigates.
                base={'S1':0.018,'S2':0.02,'S3':0.018}.get(g,0.02)
                if p=='B': base += sc.get('B_extra_churn',0.015)
                # competitor pressure can rise with time if dev not enough
                base += max(0,d-(DAY+28))*sc.get('churn_slope',0.0002)
                cr=max(0,min(0.35,base*sc.get('churn_mult',1.0)))
                kept=co['n']*(1-cr)
                revenue += kept*co['price']
                co['n']=kept
            new_co.append(co)
        cohorts=new_co
        # Lead/reputation/dev conversion path. Targeted dev should improve conversion over first month; scenario cap.
        weeks=(d-DAY)/7
        conv_ramp=1+min(sc.get('conv_ramp_cap',0.25), sc.get('conv_ramp_weekly',0.04)*weeks)
        rep=(1+sc.get('rep_weekly',0.0))**weeks
        new_subs=0.0; leads_total=0.0; init_rev=0.0
        # Ads
        for key,sp in ad_spend.items():
            # optional future ad cuts/scales
            scale=sc.get('ad_scale',1.0)
            if d>=DAY+28: scale*=sc.get('ad_scale_after_4w',1.0)
            if d>=DAY+84: scale*=sc.get('ad_scale_after_12w',1.0)
            ch,g=key
            leads=sp*scale*ad_lead_rate[key]*sc.get('lead_mult',1.0)*rep
            base=conv_ad[key]
            conv=max(0.02,min(0.9,base*sc.get('conv_mult',1.0)*conv_ramp*sc.get(f'{g}_conv_mult',1.0)))
            subs=leads*conv
            leads_total+=leads; new_subs+=subs
            if g=='S1': mixes={'A':1.0}
            else:
                # if B quality drop hurts B, reduce B share; if lower price works, maintain/increase.
                bm=plan_mix_s3_ad['B']*sc.get('B_mix_mult',1.0)
                bm=max(0.05,min(0.35,bm)); mixes={'B':bm,'A':1-bm}
            for p,frac in mixes.items():
                n=subs*frac
                pay=max(0, price[p]-lead_promo.get(g,0.0))
                init_rev += n*pay
                # half-day usage on signup day
                u=usage.get((g,p),300.0)*sc.get('usage_mult',1.0)
                units += 0.5*n*u; compute += 0.5*n*u*tier_cost.get(p,0.002)
                cohorts.append({'g':g,'p':p,'mod':d%30,'n':n,'price':price[p]})
        # Network organic leads scale with active and reputation. No ad cost but lead cost applies.
        for g,base_week in network_week.items():
            active=active_by_group.get(g,cur_active.get(g,1))
            leads=(base_week/7)*(active/max(1,cur_active.get(g,1)))**sc.get('network_elasticity',1.0)*sc.get('network_mult',1.0)*rep
            conv=max(0.02,min(0.9,conv_net[g]*sc.get('conv_mult',1.0)*conv_ramp*sc.get(f'{g}_conv_mult',1.0)))
            subs=leads*conv
            leads_total+=leads; new_subs+=subs
            if g=='S1': mixes={'A':1.0}
            elif g=='S3':
                bm=plan_mix_s3_net['B']*sc.get('B_mix_mult',1.0); bm=max(0.05,min(0.35,bm)); mixes={'B':bm,'A':1-bm}
            else: mixes={'A':1.0}
            for p,frac in mixes.items():
                n=subs*frac
                pay=max(0,price[p]-lead_promo.get(g,0.0))
                init_rev += n*pay
                u=usage.get((g,p),250.0)*sc.get('usage_mult',1.0)
                units += 0.5*n*u; compute += 0.5*n*u*tier_cost.get(p,0.002)
                cohorts.append({'g':g,'p':p,'mod':d%30,'n':n,'price':price[p]})
        # Costs/spend. Current policy; future if severe cash pressure could cut ads but keep dev until quality recovers.
        ads=sum(ad_spend.values())*sc.get('ad_scale',1.0)
        if d>=DAY+28: ads*=sc.get('ad_scale_after_4w',1.0)
        if d>=DAY+84: ads*=sc.get('ad_scale_after_12w',1.0)
        ops=2800.0
        dev=3000.0
        # optional taper after conversion recovers
        if d>=DAY+56:
            dev*=sc.get('dev_scale_after_8w',1.0)
        cap=4000.0
        if sc.get('tier3_after_4w') and d>=DAY+28: cap=1330.0
        lead_cost=0.5*leads_total
        cash += revenue + init_rev - (compute+cap+ads+ops+dev+lead_cost)
        by[d]=cash
        if d in [DAY+7,DAY+28,DAY+84,DAY+182] or d%7==0:
            det[d]={'cash':cash,'revenue':revenue,'init_rev':init_rev,'compute':compute,'ads':ads,'ops':ops,'dev':dev,'cap':cap,'lead_cost':lead_cost,'subs':sum(c['n'] for c in cohorts),'mrr':sum(c['n']*c['price'] for c in cohorts),'new_subs':new_subs,'leads':leads_total,'units':units}
    return by,det

scenarios={
 'bear': dict(conv_mult=0.75, lead_mult=0.85, network_mult=0.75, usage_mult=1.15, churn_mult=2.2, B_extra_churn=0.06, churn_slope=0.0006, rep_weekly=-0.006, conv_ramp_weekly=0.015, conv_ramp_cap=0.10, B_mix_mult=0.55, ad_scale_after_4w=0.7, dev_scale_after_8w=0.8),
 'low': dict(conv_mult=0.9, lead_mult=0.93, network_mult=0.9, usage_mult=1.07, churn_mult=1.5, B_extra_churn=0.035, churn_slope=0.00035, rep_weekly=-0.001, conv_ramp_weekly=0.03, conv_ramp_cap=0.18, B_mix_mult=0.75, ad_scale_after_4w=0.85, dev_scale_after_8w=0.9),
 'base': dict(conv_mult=1.0, lead_mult=1.0, network_mult=1.0, usage_mult=1.0, churn_mult=1.0, B_extra_churn=0.018, churn_slope=0.00018, rep_weekly=0.003, conv_ramp_weekly=0.045, conv_ramp_cap=0.28, B_mix_mult=0.9, ad_scale_after_4w=1.0, dev_scale_after_8w=0.9),
 'high': dict(conv_mult=1.15, lead_mult=1.08, network_mult=1.18, usage_mult=0.95, churn_mult=0.75, B_extra_churn=0.005, churn_slope=0.00008, rep_weekly=0.010, conv_ramp_weekly=0.06, conv_ramp_cap=0.40, B_mix_mult=1.1, ad_scale_after_4w=1.2, ad_scale_after_12w=1.3, dev_scale_after_8w=0.85),
 'very_high': dict(conv_mult=1.3, lead_mult=1.18, network_mult=1.45, usage_mult=0.9, churn_mult=0.55, B_extra_churn=0.0, churn_slope=0.0, rep_weekly=0.018, conv_ramp_weekly=0.075, conv_ramp_cap=0.55, B_mix_mult=1.35, ad_scale_after_4w=1.5, ad_scale_after_12w=1.6, dev_scale_after_8w=0.8),
}
for name,sc in scenarios.items():
    by,det=simulate(sc)
    print('\nSCENARIO',name)
    print('horizons', {h:round(by[DAY+h]) for h in [7,28,84,182]})
    for h in [7,28,84,182]:
        d=DAY+h
        dd=det[d]
        print('d',d,{k:round(v,1) for k,v in dd.items() if k in ['cash','revenue','init_rev','compute','ads','cap','lead_cost','subs','mrr','new_subs','leads','units']})

