python3 - <<'PY'
# Simple weekly projection with constant acquisition/churn, post-price MRR.
weeks=26
cash=327145
counts={'S1A':8505,'S2A':130,'S3A':6230,'S3B':993,'S3C':190}
price={'S1A':19.99,'S2A':19.99,'S3A':29.99,'S3B':99.0,'S3C':149.0}
usage={'S1A':513.1,'S2A':1103.8,'S3A':1910.7,'S3B':4099.4,'S3C':3411.0}
comp_rate={'S1A':0.002,'S2A':0.002,'S3A':0.002,'S3B':0.002,'S3C':0.006}
new_base={'S1A':930,'S2A':12,'S3A':350,'S3B':10,'S3C':55}
churn_rate={'S1A':0.015,'S2A':0.02,'S3A':0.013,'S3B':0.02,'S3C':0.01}
fixed=28000+14000+15750+11900+2100
for w in range(1,weeks+1):
    mrr=sum(counts[k]*price[k] for k in counts)
    # acquisition grows with network a bit until capacity? 1.5%/week more leads
    growth=1+0.01*min(w-1,12)
    new={k:int(new_base[k]*growth) for k in new_base}
    # churn; price shock extra S3A first 4 weeks
    churn={k:int(counts[k]*churn_rate[k]) for k in counts}
    if w<=4: churn['S3A']+=int(counts['S3A']*0.005)
    new_mrr=sum(new[k]*price[k] for k in new)
    revenue=mrr/4.286 + new_mrr
    compute=sum(counts[k]*usage[k]*comp_rate[k] for k in counts)
    # capacity tier: if daily avg based weekly units /7; peak ~1.17 avg weekday? Current peak 3.53 avg3.02 =1.17. tier5 if peak >8M
    total_units=sum(counts[k]*usage[k] for k in counts)
    avg_daily=total_units/7
    peak=avg_daily*1.17
    cap=28000 if peak<8e6 else 70000
    # if capacity tier5 adjust fixed
    cost=fixed-28000+cap+compute
    net=revenue-cost
    cash+=net
    for k in counts:
        counts[k]=counts[k]+new[k]-churn[k]
    if w in [1,4,12,26]:
        print(w, 'cash', cash, 'net', net, 'mrr', mrr, 'new_mrr', new_mrr, 'compute', compute, 'subs', sum(counts.values()), 'peak', peak, 'cap', cap)
