arguments.command:
./novamind-operation python-c "import novamind_api as nm; rows=nm.query('''SELECT ((s.billing_day_mod30 - (98%30)+30)%30) du, SUM(s.seat_count*s.effective_price) amt FROM subscriptions s WHERE s.status=\"subscribed\" GROUP BY du''')['rows']; d={r['du']:r['amt'] for r in rows};
for horizon in [7,28,30]: print(horizon, sum(v for k,v in d.items() if 1<=k<=horizon), 'incl0', sum(v for k,v in d.items() if 0<=k<=horizon));
print('sum all', sum(d.values()))"

