arguments.command:
./novamind-operation python-c "import novamind_api as nm,json; D=nm.vars.current_day; 
for a,b in [(92,98),(85,91),(78,84),(99,105)]:
 sql=f'''SELECT c.acquisition_source,c.group_id, COUNT(*) leads, SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) subs, ROUND(100.0*SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END)/COUNT(*),2) conv, ROUND(SUM(CASE WHEN l.amount IS NOT NULL THEN l.amount ELSE 0 END),2) rev FROM customers c JOIN subscriptions s ON c.customer_id=s.customer_id LEFT JOIN ledger l ON l.category='subscription_payment' AND CAST(REPLACE(l.note,'Subscription payment from customer ', '') AS INTEGER)=c.customer_id AND l.day BETWEEN {a} AND {b} WHERE c.created_day BETWEEN {a} AND {b} GROUP BY c.acquisition_source,c.group_id ORDER BY leads DESC'''
 print('---',a,b,'---'); print(json.dumps(nm.query(sql)['rows'],indent=2))"

