arguments.command:
./novamind-operation python-c "import novamind_api as nm; D=nm.vars.current_day; rows=nm.query('SELECT billing_day_mod30 mod, SUM(effective_price*seat_count) eff, SUM(listed_price*seat_count) list FROM subscriptions WHERE status=\"subscribed\" GROUP BY billing_day_mod30')['rows'];
for horizon in [7,28,84,182]:
 eff=sum(r['eff'] for r in rows for day in range(D+1,D+horizon+1) if day%30==r['mod'])
 listv=sum(r['list'] for r in rows for day in range(D+1,D+horizon+1) if day%30==r['mod'])
 print(horizon, round(eff,2), round(listv,2), round(listv-eff,2))"

