./novamind-operation python-c "import novamind_api as nm, json; 
for tbl in ['config_history','config_overrides','service_day','ad_channel_leads','notifications','agent_social_media_posts']:
 print('---',tbl,'---')
 try:
  r=nm.query(f'SELECT * FROM {tbl} ORDER BY day DESC LIMIT 5')
  print(json.dumps(r['rows'],indent=2,default=str)[:5000])
 except Exception as e: print(e)
"

./novamind-operation python-c "import novamind_api as nm,json; D=nm.vars.current_day; r=nm.query(f'''SELECT c.group_id,s.plan,COUNT(*) n,ROUND(SUM(s.effective_price),2) lost_mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day BETWEEN {D-6} AND {D} GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan'''); print(json.dumps(r['rows'],indent=2));
# active billed last 7 approximated: active now + cancels end day by billing day? count billed payments by group plan this week
r=nm.query(f'''SELECT c.group_id,s.plan,COUNT(*) entries,ROUND(SUM(l.amount),2) amount FROM ledger l JOIN subscriptions s ON l.subscription_id=s.subscription_id JOIN customers c ON s.customer_id=c.customer_id WHERE l.category='subscription_payment' AND l.day BETWEEN {D-6} AND {D} GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan'''); print(json.dumps(r['rows'],indent=2))"

./novamind-operation python-c "import novamind_api as nm,json; 
print('config',json.dumps(nm.query('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')['rows'],indent=2));
print('overrides',json.dumps(nm.query('SELECT day,tool_name,setting_type,settings_json FROM config_overrides ORDER BY id DESC LIMIT 10')['rows'],indent=2));
print('agent post',json.dumps(nm.query('SELECT * FROM agent_social_media_posts ORDER BY day DESC, agent_post_id DESC LIMIT 2')['rows'],indent=2)[:2000])"

./novamind-operation python-c "import novamind_api as nm; D=nm.vars.current_day; 
for n in [7,14,21,28,35,84,182]:
 days=' UNION ALL '.join([f'SELECT {d} AS day' for d in range(D+1,D+n+1)])
 r=nm.query(f'''WITH days AS ({days}) SELECT ROUND(SUM(s.effective_price),2) amount, COUNT(s.subscription_id) n FROM days JOIN subscriptions s ON s.status='subscribed' AND (days.day%30)=s.billing_day_mod30 AND days.day>=s.start_day''')['rows'][0]
 print(n,r)
"

