cat > forecast_day161.py <<'PY'
import novamind_api as nm, random, math, statistics, json
DAY=nm.vars.current_day
cash0=nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash']
rows=nm.query('''
SELECT c.group_id,s.plan,ROUND(s.effective_price,2) price,s.billing_day_mod30,COUNT(*) n
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE s.status='subscribed' AND c.customer_type='small'
GROUP BY c.group_id,s.plan,ROUND(s.effective_price,2),s.billing_day_mod30
''')['rows']
# Current Day161 action: A tier1, B tier2, C tier3; prices 19.99/79/169; total ops/dev 3.5k/2.5k per day.
usage_base={('S1','A'):76.5,('S2','A'):161.7,('S3','A'):279.2,('S3','B'):551.0,('S3','C'):468.4}
cost_per={'A':0.0003,'B':0.002,'C':0.006}
new_prices={'A':19.99,'B':79.0,'C':169.0}
# Lead promo affects acquisition; first cash in observed data generally books at effective price, so use list prices.
first_price={('S1','A'):19.99,('S2','A'):19.99,('S3','A'):19.99,('S3','B'):79.0,('S3','C'):169.0}

def daily_spend(params,t,cash,modeled_units):
    # Adaptation we are likely to do in future weeks if cash gets tight or active issues stay controlled.
    if cash < params.get('crisis_cash',150000):
        return params.get('ops_crisis',2500), params.get('dev_crisis',800)
    if cash < params.get('caution_cash',185000):
        return params.get('ops_caution',3000), params.get('dev_caution',1400)
    if t > params.get('trim_after_days',42):
        return params.get('ops_later',3200), params.get('dev_later',1500)
    return params.get('ops',3500), params.get('dev',2500)

def simulate(params, seed=0, days=182):
    random.seed(seed)
    state={}
    for r in rows:
        key=(r['group_id'],r['plan'],float(r['price']),int(r['billing_day_mod30']))
        state[key]=state.get(key,0)+float(r['n'])
    cash=float(cash0); weekly=[]
    for t in range(1,days+1):
        day=DAY+t; week=t/7.0
        new_state={}
        # Billing / churn / plan choice
        for (g,p,price,bm),n in list(state.items()):
            if n<=0: continue
            if bm==day%30:
                base_ch=params['churn'].get((g,p),0.05)
                base_ch *= max(0.2, 1 + params.get('churn_drift_per_week',0.0)*week)
                sd=max(0.003, abs(base_ch)*params.get('churn_cv',0.22))
                ch=max(0,min(0.65, random.gauss(base_ch,sd)))
                remain=n*(1-ch)
                def rr(name, default, cap=0.45):
                    val=params.get(name, default)
                    val *= max(0.2, 1+params.get(name+'_trend',0.0)*week)
                    return max(0,min(cap,random.gauss(val, max(0.004,abs(val)*params.get('move_cv',0.30)))))
                moves=[]
                if g=='S3' and p=='A':
                    # A tier1 should again push dissatisfied power users toward paid higher tiers, though some cancel.
                    toC=rr('s3a_to_c',0.10); toB=rr('s3a_to_b',0.08)
                    tot=min(0.42,toC+toB); scale=1 if toC+toB<=tot or toC+toB==0 else tot/(toC+toB)
                    nc=remain*toC*scale; nb=remain*toB*scale; stay=remain-nc-nb
                    moves=[('A',price,stay),('B',new_prices['B'],nb),('C',new_prices['C'],nc)]
                elif g=='S3' and p=='B':
                    toC=rr('s3b_to_c',0.13); toA=rr('s3b_to_a',0.03)  # A1 makes downgrades less attractive
                    tot=min(0.35,toC+toA); scale=1 if toC+toA<=tot or toC+toA==0 else tot/(toC+toA)
                    nc=remain*toC*scale; na=remain*toA*scale; stay=remain-nc-na
                    moves=[('B',price if price<new_prices['B']+0.01 else new_prices['B'],stay),('C',new_prices['C'],nc),('A',new_prices['A'],na)]
                elif g=='S3' and p=='C':
                    toB=rr('s3c_to_b',0.025); toA=rr('s3c_to_a',0.004)
                    tot=min(0.18,toB+toA); scale=1 if toB+toA<=tot or toB+toA==0 else tot/(toB+toA)
                    nb=remain*toB*scale; na=remain*toA*scale; stay=remain-nb-na
                    moves=[('C',price,stay),('B',new_prices['B'],nb),('A',new_prices['A'],na)]
                elif g=='S2' and p=='A':
                    moves=[('A',price,remain)]
                else:
                    moves=[(p,price,remain)]
                for p2,pr,cnt in moves:
                    if cnt<=0: continue
                    cash += cnt*pr
                    key=(g,p2,pr,bm)
                    new_state[key]=new_state.get(key,0)+cnt
            else:
                new_state[(g,p,price,bm)]=new_state.get((g,p,price,bm),0)+n
        state=new_state
        # Organic/network leads; A1 means conversion likely falls back near zero, partially cushioned by lead promo and social post.
        lead_mult=params.get('lead_mult',1.0)*math.exp(params.get('lead_trend',0.0)*week)
        social=params.get('social_effect',0.0)*math.exp(-week/7.0)
        lead_mult*=max(0.45,1+social)
        leads_s1=max(0, random.gauss(params.get('leads_s1',195)*lead_mult, params.get('lead_noise',1.0)*35))
        leads_s2=max(0, random.gauss(params.get('leads_s2',18)*lead_mult, params.get('lead_noise',1.0)*7))
        leads_s3=max(0, random.gauss(params.get('leads_s3',61)*lead_mult, params.get('lead_noise',1.0)*18))
        # conversion has immediate start and may improve if cumulative dev raises A1 quality; severe uncertainty.
        def interp(start,end,half=8):
            a=1-math.exp(-week/half); return start+(end-start)*a
        c_s1=max(0,min(0.12,random.gauss(interp(params.get('conv_s1_start',0.001),params.get('conv_s1_end',0.010),params.get('conv_half',10)),params.get('conv_noise',0.55)*max(0.001,interp(params.get('conv_s1_start',0.001),params.get('conv_s1_end',0.010),params.get('conv_half',10))))))
        c_s2=max(0,min(0.05,random.gauss(interp(params.get('conv_s2_start',0.0),params.get('conv_s2_end',0.002),params.get('conv_half',10)),0.0015)))
        c_s3=max(0,min(0.08,random.gauss(interp(params.get('conv_s3_start',0.0005),params.get('conv_s3_end',0.006),params.get('conv_half',12)),params.get('conv_noise',0.55)*max(0.001,interp(params.get('conv_s3_start',0.0005),params.get('conv_s3_end',0.006),params.get('conv_half',12))))))
        s1=leads_s1*c_s1; s2=leads_s2*c_s2; s3=leads_s3*c_s3
        s3c=s3*params.get('new_s3_c_share',0.08); s3b=s3*params.get('new_s3_b_share',0.14); s3a=max(0,s3-s3c-s3b)
        bm=day%30
        def add(g,p,pr,cnt):
            nonlocal cash
            if cnt<=0: return
            cash += cnt*first_price.get((g,p),pr)
            key=(g,p,pr,bm)
            state[key]=state.get(key,0)+cnt
        add('S1','A',new_prices['A'],s1); add('S2','A',new_prices['A'],s2)
        add('S3','A',new_prices['A'],s3a); add('S3','B',new_prices['B'],s3b); add('S3','C',new_prices['C'],s3c)
        cash -= 0.5*(leads_s1+leads_s2+leads_s3)
        # Costs
        comp=0.0; modeled_units=0.0
        for (g,p,price,bm),n in state.items():
            u=usage_base.get((g,p),usage_base.get((g,'A'),120))*params.get('usage_mult',1.0)
            if g=='S3' and p in ('B','C'):
                u *= (1+params.get('bc_usage_lift',0.00)*min(1,week/8.0))
            modeled_units += n*u
            comp += n*u*cost_per[p]
        comp*=max(0.55, random.gauss(1.0,params.get('compute_cv',0.05)))
        capacity=4000
        if params.get('allow_cap_down',False) and t>params.get('cap_down_after',70) and modeled_units < params.get('cap_down_avg_units',1750000):
            capacity=1330
        ops,dev=daily_spend(params,t,cash,modeled_units)
        cash -= capacity+ops+dev+comp
        if t%7==0: weekly.append(cash)
    return weekly

