import novamind_api as nm, random, math, statistics, json
DAY=nm.vars.current_day
cash0=nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash']
rows=nm.query('''
SELECT c.group_id,s.plan,ROUND(s.effective_price,2) price,s.billing_day_mod30,COUNT(*) n
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE s.status='subscribed' AND c.customer_type='small'
GROUP BY c.group_id,s.plan,ROUND(s.effective_price,2),s.billing_day_mod30
''')['rows']
usage_base={('S1','A'):76.7,('S2','A'):160.0,('S2','B'):168.0,('S3','A'):278.5,('S3','B'):477.5,('S3','C'):462.5}
cost_per={'A':0.0003,'B':0.002,'C':0.006}
# Day168 action: A/B/C list 19.99/79/159, A1/B2/C3, S3 C ongoing promo $10, high first-period promos.
new_prices={'A':19.99,'B':79.0,'C':149.0}  # ongoing effective prices for new subscriptions after plan promo
first_price={('S1','A'):0.99,('S2','A'):0.99,('S3','A'):0.0,('S3','B'):54.0,('S3','C'):124.0}

def charge_price(g,p,price):
    if g=='S3' and p=='C':
        return max(0.0, price-10.0)  # ongoing plan-C promo applies to grandfathered C
    return price

def daily_spend(params,t,cash,modeled_units):
    if cash < params.get('crisis_cash',145000):
        return params.get('ops_crisis',2300), params.get('dev_crisis',700)
    if cash < params.get('caution_cash',175000):
        return params.get('ops_caution',2900), params.get('dev_caution',1300)
    if t > params.get('trim_after_days',56):
        return params.get('ops_later',3100), params.get('dev_later',1700)
    return params.get('ops',3400), params.get('dev',2500)

def simulate(params, seed=0, days=182):
    random.seed(seed)
    state={}
    for r in rows:
        key=(r['group_id'],r['plan'],float(r['price']),int(r['billing_day_mod30']))
        state[key]=state.get(key,0)+float(r['n'])
    cash=float(cash0); weekly=[]
    for t in range(1,days+1):
        day=DAY+t; week=t/7.0
        new_state={}
        for (g,p,price,bm),n in list(state.items()):
            if n<=0: continue
            if bm==day%30:
                # Churn varies by plan/price; older lower-priced cohorts get modest loyalty benefit.
                base_ch=params['churn'].get((g,p),0.05)
                if g=='S3' and p=='A' and price>=19.99: base_ch*=params.get('s3a_20_churn_mult',1.15)
                if g=='S3' and p=='B' and price>=110: base_ch*=params.get('s3b_high_churn_mult',1.55)
                if g=='S3' and p=='C' and price>=160: base_ch*=params.get('s3c_high_churn_mult',1.25)
                base_ch *= max(0.25, 1 + params.get('churn_drift_per_week',0.0)*week)
                sd=max(0.003, abs(base_ch)*params.get('churn_cv',0.22))
                ch=max(0,min(0.70, random.gauss(base_ch,sd)))
                remain=n*(1-ch)
                def rr(name, default, cap=0.45):
                    val=params.get(name, default) * max(0.25,1+params.get(name+'_trend',0.0)*week)
                    return max(0,min(cap,random.gauss(val, max(0.004,abs(val)*params.get('move_cv',0.30)))))
                if g=='S3' and p=='A':
                    toB=rr('s3a_to_b',0.10); toC=rr('s3a_to_c',0.035)
                    tot=min(0.42,toB+toC); scale=1 if toB+toC<=tot or toB+toC==0 else tot/(toB+toC)
                    nb=remain*toB*scale; nc=remain*toC*scale; stay=remain-nb-nc
                    moves=[('A',price,stay),('B',new_prices['B'],nb),('C',new_prices['C'],nc)]
                elif g=='S3' and p=='B':
                    toC=rr('s3b_to_c',0.09); toA=rr('s3b_to_a',0.025)
                    tot=min(0.35,toC+toA); scale=1 if toC+toA<=tot or toC+toA==0 else tot/(toC+toA)
                    nc=remain*toC*scale; na=remain*toA*scale; stay=remain-nc-na
                    # when a B user changes/recontracts, use current effective B=79; otherwise grandfathered price persists
                    moves=[('B',price,stay),('C',new_prices['C'],nc),('A',new_prices['A'],na)]
                elif g=='S3' and p=='C':
                    # C promo should reduce downgrades but not eliminate them under quality drift.
                    toB=rr('s3c_to_b',0.020); toA=rr('s3c_to_a',0.003)
                    tot=min(0.18,toB+toA); scale=1 if toB+toA<=tot or toB+toA==0 else tot/(toB+toA)
                    nb=remain*toB*scale; na=remain*toA*scale; stay=remain-nb-na
                    moves=[('C',price,stay),('B',new_prices['B'],nb),('A',new_prices['A'],na)]
                elif g=='S2' and p=='A':
                    # Some quality-focused users may upgrade to B if promo/trial keeps the segment warm.
                    toB=rr('s2a_to_b',0.006,0.12); nb=remain*toB; moves=[('A',price,remain-nb),('B',new_prices['B'],nb)]
                else:
                    moves=[(p,price,remain)]
                for p2,pr,cnt in moves:
                    if cnt<=0: continue
                    cash += cnt*charge_price(g,p2,pr)
                    key=(g,p2,pr,bm)
                    new_state[key]=new_state.get(key,0)+cnt
            else:
                new_state[(g,p,price,bm)]=new_state.get((g,p,price,bm),0)+n
        state=new_state
        # Network leads. High first-period promos should raise conversion, with renewal value depending on dev catch-up.
        lead_mult=params.get('lead_mult',1.0)*math.exp(params.get('lead_trend',0.0)*week)
        social=params.get('social_effect',0.0)*math.exp(-week/6.0)
        lead_mult*=max(0.35,1+social)
        leads_s1=max(0, random.gauss(params.get('leads_s1',197)*lead_mult, params.get('lead_noise',1.0)*36))
        leads_s2=max(0, random.gauss(params.get('leads_s2',16)*lead_mult, params.get('lead_noise',1.0)*7))
        leads_s3=max(0, random.gauss(params.get('leads_s3',67)*lead_mult, params.get('lead_noise',1.0)*18))
        def interp(start,end,half=8):
            a=1-math.exp(-week/half); return start+(end-start)*a
        mu1=interp(params.get('conv_s1_start',0.04),params.get('conv_s1_end',0.18),params.get('conv_half',8))
        mu2=interp(params.get('conv_s2_start',0.005),params.get('conv_s2_end',0.03),params.get('conv_half',10))
        mu3=interp(params.get('conv_s3_start',0.010),params.get('conv_s3_end',0.055),params.get('conv_half',10))
        c_s1=max(0,min(0.65,random.gauss(mu1,params.get('conv_noise',0.45)*max(0.004,mu1))))
        c_s2=max(0,min(0.25,random.gauss(mu2,params.get('conv_noise',0.55)*max(0.003,mu2))))
        c_s3=max(0,min(0.35,random.gauss(mu3,params.get('conv_noise',0.50)*max(0.003,mu3))))
        s1=leads_s1*c_s1; s2=leads_s2*c_s2; s3=leads_s3*c_s3
        s3c=s3*params.get('new_s3_c_share',0.10); s3b=s3*params.get('new_s3_b_share',0.22); s3a=max(0,s3-s3c-s3b)
        bm=day%30
        def add(g,p,pr,cnt):
            nonlocal cash
            if cnt<=0: return
            cash += cnt*first_price.get((g,p),charge_price(g,p,pr))
            key=(g,p,pr,bm)
            state[key]=state.get(key,0)+cnt
        add('S1','A',new_prices['A'],s1); add('S2','A',new_prices['A'],s2)
        add('S3','A',new_prices['A'],s3a); add('S3','B',new_prices['B'],s3b); add('S3','C',new_prices['C'],s3c)
        cash -= 0.5*(leads_s1+leads_s2+leads_s3)
        # Costs
        comp=0.0; modeled_units=0.0
        for (g,p,price,bm),n in state.items():
            u=usage_base.get((g,p),usage_base.get((g,'A'),120))*params.get('usage_mult',1.0)
            if g=='S3' and p in ('B','C'):
                u *= (1+params.get('bc_usage_lift',0.00)*min(1,week/8.0))
            modeled_units += n*u
            comp += n*u*cost_per[p]
        comp*=max(0.55, random.gauss(1.0,params.get('compute_cv',0.05)))
        capacity=4000
