import novamind_api as nm, random, math, statistics, json
DAY=nm.vars.current_day
cash0=float(nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash'])
rows=nm.query('''
SELECT c.group_id,s.plan,ROUND(s.effective_price,2) price,s.billing_day_mod30,COUNT(*) n
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE s.status='subscribed' AND c.customer_type='small'
GROUP BY c.group_id,s.plan,ROUND(s.effective_price,2),s.billing_day_mod30
''')['rows']
# Last-7 actual average daily usage/customer; A quota was raised 550->750, so A has a small latent-use lift.
usage_base={('S1','A'):79.0,('S1','B'):115.0,('S2','A'):168.0,('S2','B'):175.0,('S3','A'):305.0,('S3','B'):425.0,('S3','C'):445.0}
cost_per={'A':0.0003,'B':0.002,'C':0.006}
new_prices={'A':19.99,'B':79.0,'C':159.0}
# First-period lead promo after Day182 actions: S1 A free-ish; S3 $100 lead promo + $10 C recurring credit.
first_price={('S1','A'):1.0,('S2','A'):1.0,('S3','A'):0.0,('S3','B'):0.0,('S3','C'):49.0}

def s3c_promo_for_price(price):
    # group-plan C credit $10 for all S3 C; customer-specific extra for legacy C169/C249.
    if price >= 200: return 110.0
    if price >= 169: return 20.0
    return 10.0

def charge_price(g,p,price):
    if g=='S3' and p=='C':
        return max(0.0, price - s3c_promo_for_price(price))
    return price

def churn_for(params,g,p,price,week):
    # Work with net price for promoted C legacy users.
    net=charge_price(g,p,price)
    base=params['churn'].get((g,p),0.05)
    if g=='S1' and p=='A':
        if net >= 19.99: base *= params.get('s1a_20_mult',1.0)
        elif net <= 17.99: base *= params.get('s1a_low_mult',0.85)
    if g=='S3' and p=='A':
        if net >= 19.99: base *= params.get('s3a_20_mult',1.25)
        if net <= 17.99: base *= params.get('s3a_low_mult',0.75)
    if g=='S3' and p=='B':
        if net <= 79.0: base *= params.get('s3b_79_mult',0.25)
        elif net >= 110: base *= params.get('s3b_high_mult',1.25)
        elif net >= 95: base *= params.get('s3b_mid_mult',1.3)
    if g=='S3' and p=='C':
        # C churn is now primarily net-price driven; net<=149 performed 0-1.4% last week.
        if net <= 149: base *= params.get('s3c_good_mult',0.55)
        elif net >= 159: base *= params.get('s3c_bad_mult',5.0)
    base *= max(0.30, 1 + params.get('churn_drift_per_week',0.0)*week)
    sd=max(0.003, abs(base)*params.get('churn_cv',0.25))
    return max(0,min(params.get('max_churn',0.70), random.gauss(base,sd)))

def daily_spend(params,t,cash,modeled_units):
    # Intended future policy: hold high support/dev while cash is safe; trim if cash falls or after backlog/reputation stabilizes.
    if cash < params.get('crisis_cash',145000):
        return params.get('ops_crisis',2200), params.get('dev_crisis',600)
    if cash < params.get('caution_cash',180000):
        return params.get('ops_caution',2900), params.get('dev_caution',1200)
    if t > params.get('trim_after_days',56):
        return params.get('ops_later',3200), params.get('dev_later',1600)
    return params.get('ops',4000), params.get('dev',2500)

def simulate(params, seed=0, days=182):
    random.seed(seed)
    state={}
    for r in rows:
        key=(r['group_id'],r['plan'],float(r['price']),int(r['billing_day_mod30']))
        state[key]=state.get(key,0)+float(r['n'])
    cash=cash0; weekly=[]; cap_tier4=True
    for t in range(1,days+1):
        day=DAY+t; week=t/7.0
        new_state={}
        for (g,p,price,bm),n in list(state.items()):
            if n<=0: continue
            if bm==day%30:
                ch=churn_for(params,g,p,price,week)
                remain=n*(1-ch)
                # Limited plan movement; active table has shown little net upgrade recently, so keep moves conservative.
                def rr(name, default, cap=0.30):
                    val=params.get(name, default) * max(0.20, 1+params.get(name+'_trend',0.0)*week)
                    return max(0,min(cap,random.gauss(val, max(0.003,abs(val)*params.get('move_cv',0.30)))))
                moves=[]
                if g=='S3' and p=='A':
                    toB=rr('s3a_to_b',0.035); toC=rr('s3a_to_c',0.010)
                    tot=min(0.18,toB+toC); scale=1 if toB+toC<=tot or toB+toC==0 else tot/(toB+toC)
                    nb=remain*toB*scale; nc=remain*toC*scale; moves=[('A',price,remain-nb-nc),('B',new_prices['B'],nb),('C',new_prices['C'],nc)]
                elif g=='S3' and p=='B':
                    toC=rr('s3b_to_c',0.035); toA=rr('s3b_to_a',0.012)
                    tot=min(0.16,toC+toA); scale=1 if toC+toA<=tot or toC+toA==0 else tot/(toC+toA)
                    nc=remain*toC*scale; na=remain*toA*scale; moves=[('B',price,remain-nc-na),('C',new_prices['C'],nc),('A',new_prices['A'],na)]
                elif g=='S3' and p=='C':
                    toB=rr('s3c_to_b',0.010); toA=rr('s3c_to_a',0.001)
                    tot=min(0.08,toB+toA); scale=1 if toB+toA<=tot or toB+toA==0 else tot/(toB+toA)
                    nb=remain*toB*scale; na=remain*toA*scale; moves=[('C',price,remain-nb-na),('B',new_prices['B'],nb),('A',new_prices['A'],na)]
                elif g=='S2' and p=='A':
                    toB=rr('s2a_to_b',0.003,0.08); nb=remain*toB; moves=[('A',price,remain-nb),('B',new_prices['B'],nb)]
                else:
                    moves=[(p,price,remain)]
                for p2,pr,cnt in moves:
                    if cnt<=0: continue
                    cash += cnt*charge_price(g,p2,pr)
                    new_state[(g,p2,pr,bm)]=new_state.get((g,p2,pr,bm),0)+cnt
            else:
                new_state[(g,p,price,bm)]=new_state.get((g,p,price,bm),0)+n
        state=new_state
        # Network/referral lead flow calibrated to last two weeks; conversion uncertain under social/competitor pressure.
        lead_mult=params.get('lead_mult',1.0)*math.exp(params.get('lead_trend',0.0)*week)
        leads_s1=max(0, random.gauss(params.get('leads_s1',215)*lead_mult, params.get('lead_noise',1.0)*38))
        leads_s2=max(0, random.gauss(params.get('leads_s2',18)*lead_mult, params.get('lead_noise',1.0)*8))
        leads_s3=max(0, random.gauss(params.get('leads_s3',68)*lead_mult, params.get('lead_noise',1.0)*20))
        # Day182 S3 promo bump may lift S3 conversion, but persistent support/rate-limit complaints keep base modest.
        def interp(start,end,half=8):
            a=1-math.exp(-week/half); return start+(end-start)*a
        c_s1=max(0,min(0.30,random.gauss(interp(params.get('conv_s1_start',0.023),params.get('conv_s1_end',0.050),params.get('conv_half',10)), params.get('conv_noise',0.45)*0.018)))
        c_s2=max(0,min(0.12,random.gauss(interp(params.get('conv_s2_start',0.000),params.get('conv_s2_end',0.010),12), params.get('conv_noise',0.55)*0.006)))
        c_s3=max(0,min(0.20,random.gauss(interp(params.get('conv_s3_start',0.012),params.get('conv_s3_end',0.035),params.get('conv_half',10)), params.get('conv_noise',0.50)*0.012)))
        s1=leads_s1*c_s1; s2=leads_s2*c_s2; s3=leads_s3*c_s3
        s3c=s3*params.get('new_s3_c_share',0.70); s3b=s3*params.get('new_s3_b_share',0.20); s3a=max(0,s3-s3c-s3b)
        bm=day%30
        def add(g,p,pr,cnt):
            nonlocal cash
            if cnt<=0: return
            cash += cnt*first_price.get((g,p),charge_price(g,p,pr))
            state[(g,p,pr,bm)]=state.get((g,p,pr,bm),0)+cnt
        add('S1','A',new_prices['A'],s1); add('S2','A',new_prices['A'],s2)
        add('S3','A',new_prices['A'],s3a); add('S3','B',new_prices['B'],s3b); add('S3','C',new_prices['C'],s3c)
        cash -= 0.5*(leads_s1+leads_s2+leads_s3)
        # Costs from current subscribers. Capacity can drop to tier3 once modeled average demand is safely below weekday cap.
        comp=0.0; modeled_units=0.0
        for (g,p,price,bm),n in state.items():
            u=usage_base.get((g,p),usage_base.get((g,'A'),120))*params.get('usage_mult',1.0)
            modeled_units += n*u
            comp += n*u*cost_per[p]
        comp*=max(0.60, random.gauss(1.0,params.get('compute_cv',0.06)))
        capacity=4000
        if params.get('allow_cap_down',False) and t>params.get('cap_down_after',56) and modeled_units < params.get('cap_down_avg_units',1950000):
            capacity=1330
        ops,dev=daily_spend(params,t,cash,modeled_units)
        cash -= capacity+ops+dev+comp
        if t%7==0: weekly.append(cash)
    return weekly

