import novamind_api as nm, random, math, statistics
DAY=nm.vars.current_day
cash0=float(nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash'])
rows=nm.query('''
SELECT c.group_id,s.plan,ROUND(s.effective_price,2) price,s.billing_day_mod30,COUNT(*) n
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE s.status='subscribed' AND c.customer_type='small'
GROUP BY c.group_id,s.plan,ROUND(s.effective_price,2),s.billing_day_mod30
''')['rows']
# Last-7 actual usage/customer/day after A quota 750.
usage_base={('S1','A'):76.6,('S1','B'):108.6,('S2','A'):170.0,('S2','B'):201.8,('S3','A'):292.6,('S3','B'):411.5,('S3','C'):415.4}
cost_per={'A':0.0003,'B':0.002,'C':0.006}
new_prices={'A':19.99,'B':79.0,'C':159.0}
# Current lead promos: S1 free-ish first A, S3 $100 lead promo plus S3-C recurring $10 -> C first bill ~$49.
first_price={('S1','A'):1.0,('S2','A'):1.0,('S3','A'):0.0,('S3','B'):0.0,('S3','C'):49.0}

def charge_price(g,p,price):
    # Use active effective prices directly, except for Day189 deeper targeted save on legacy C169/C249.
    if g=='S3' and p=='C':
        if price >= 240: return 119.0       # 249 legacy after 120 customer + 10 group credits (approx)
        if price >= 168.5: return 129.0     # 169 legacy after 30 customer + 10 group credits (approx)
    return price

def churn_for(params,g,p,price,week):
    # Churn evaluated on billing. Latest billed cohort had very high A churn, low B79/C149 churn, C169 uncertainty after new save.
    base=params['churn'].get((g,p),0.05)
    net=charge_price(g,p,price)
    if g=='S1' and p=='A':
        if price >= 29: base *= params.get('s1a_high_mult',1.25)
        elif price <= 17.99: base *= params.get('s1a_low_mult',0.75)
    if g=='S3' and p=='A':
        if price >= 29: base *= params.get('s3a_high_mult',1.45)
        elif price <= 17.99: base *= params.get('s3a_low_mult',0.70)
    if g=='S3' and p=='B':
        if price <= 79: base *= params.get('s3b_79_mult',0.35)
        elif price >= 110: base *= params.get('s3b_high_mult',2.0)
        elif price >= 95: base *= params.get('s3b_mid_mult',1.4)
    if g=='S3' and p=='C':
        if price >= 240: base *= params.get('s3c_249_mult',6.0)
        elif price >= 168.5: base *= params.get('s3c_169_mult',5.0)  # new promo may reduce but cohort risk remains
        elif net <= 149: base *= params.get('s3c_good_mult',0.55)
        elif net >= 159: base *= params.get('s3c_mid_mult',1.0)
    base *= max(0.25, 1 + params.get('churn_drift_per_week',0.0)*week)
    sd=max(0.004, abs(base)*params.get('churn_cv',0.28))
    return max(0,min(params.get('max_churn',0.80), random.gauss(base,sd)))

def daily_spend(params,t,cash,modeled_units):
    # Planned policy: keep temporary support surge while cash >~190k, then trim; later trim once backlog/social stabilizes.
    if cash < params.get('crisis_cash',145000):
        return params.get('ops_crisis',2200), params.get('dev_crisis',500)
    if cash < params.get('caution_cash',185000):
        return params.get('ops_caution',3000), params.get('dev_caution',1200)
    if t > params.get('trim_after_days',56):
        return params.get('ops_later',3300), params.get('dev_later',1600)
    return params.get('ops',4500), params.get('dev',2500)

def simulate(params,seed=0,days=182):
    random.seed(seed)
    state={}
    for r in rows:
        key=(r['group_id'],r['plan'],float(r['price']),int(r['billing_day_mod30']))
        state[key]=state.get(key,0)+float(r['n'])
    cash=cash0; weekly=[]
    for t in range(1,days+1):
        day=DAY+t; week=t/7.0
        new_state={}
        for (g,p,price,bm),n in list(state.items()):
            if n<=0: continue
            if bm==day%30:
                ch=churn_for(params,g,p,price,week)
                remain=n*(1-ch)
                def rr(name,default,cap=0.50):
                    val=params.get(name,default)*max(0.2,1+params.get(name+'_trend',0.0)*week)
                    return max(0,min(cap,random.gauss(val,max(0.004,abs(val)*params.get('move_cv',0.32)))))
                moves=[]
                if g=='S3' and p=='A':
                    toB=rr('s3a_to_b',0.20,0.45); toC=rr('s3a_to_c',0.08,0.30)
                    tot=min(0.55,toB+toC); scale=1 if toB+toC<=tot or toB+toC==0 else tot/(toB+toC)
                    nb=remain*toB*scale; nc=remain*toC*scale
                    moves=[('A',price,remain-nb-nc),('B',new_prices['B'],nb),('C',new_prices['C'],nc)]
                elif g=='S3' and p=='B':
                    toC=rr('s3b_to_c',0.06,0.30); toA=rr('s3b_to_a',0.018,0.18)
                    tot=min(0.35,toC+toA); scale=1 if toC+toA<=tot or toC+toA==0 else tot/(toC+toA)
                    nc=remain*toC*scale; na=remain*toA*scale
                    moves=[('B',price,remain-nc-na),('C',new_prices['C'],nc),('A',new_prices['A'],na)]
                elif g=='S3' and p=='C':
                    toB=rr('s3c_to_b',0.012,0.15); toA=rr('s3c_to_a',0.002,0.08)
                    tot=min(0.18,toB+toA); scale=1 if toB+toA<=tot or toB+toA==0 else tot/(toB+toA)
                    nb=remain*toB*scale; na=remain*toA*scale
                    moves=[('C',price,remain-nb-na),('B',new_prices['B'],nb),('A',new_prices['A'],na)]
                elif g=='S2' and p=='A':
                    toB=rr('s2a_to_b',0.02,0.20); nb=remain*toB; moves=[('A',price,remain-nb),('B',new_prices['B'],nb)]
                else:
                    moves=[(p,price,remain)]
                for p2,pr,cnt in moves:
                    if cnt<=0: continue
                    cash += cnt*charge_price(g,p2,pr)
                    new_state[(g,p2,pr,bm)] = new_state.get((g,p2,pr,bm),0)+cnt
            else:
                new_state[(g,p,price,bm)] = new_state.get((g,p,price,bm),0)+n
        state=new_state
        # Organic leads calibrated to last week (~272/day total); conversion currently near zero, may recover if support post/ops help.
        lead_mult=params.get('lead_mult',1.0)*math.exp(params.get('lead_trend',0.0)*week)
        leads_s1=max(0, random.gauss(params.get('leads_s1',196)*lead_mult, params.get('lead_noise',1.0)*35))
        leads_s2=max(0, random.gauss(params.get('leads_s2',15)*lead_mult, params.get('lead_noise',1.0)*7))
        leads_s3=max(0, random.gauss(params.get('leads_s3',60)*lead_mult, params.get('lead_noise',1.0)*18))
        def interp(start,end,half=10):
            a=1-math.exp(-week/half); return start+(end-start)*a
        c_s1=max(0,min(0.20,random.gauss(interp(params.get('conv_s1_start',0.001),params.get('conv_s1_end',0.025),params.get('conv_half',12)), params.get('conv_noise',0.6)*0.010)))
        c_s2=max(0,min(0.10,random.gauss(interp(params.get('conv_s2_start',0.0),params.get('conv_s2_end',0.006),14), params.get('conv_noise',0.6)*0.004)))
        c_s3=max(0,min(0.18,random.gauss(interp(params.get('conv_s3_start',0.004),params.get('conv_s3_end',0.025),params.get('conv_half',12)), params.get('conv_noise',0.6)*0.009)))
        s1=leads_s1*c_s1; s2=leads_s2*c_s2; s3=leads_s3*c_s3
        s3c=s3*params.get('new_s3_c_share',0.75); s3b=s3*params.get('new_s3_b_share',0.15); s3a=max(0,s3-s3c-s3b)
        bm=day%30
        def add(g,p,pr,cnt):
            nonlocal cash
            if cnt<=0: return
            cash += cnt*first_price.get((g,p),charge_price(g,p,pr))
            state[(g,p,pr,bm)] = state.get((g,p,pr,bm),0)+cnt
        add('S1','A',new_prices['A'],s1); add('S2','A',new_prices['A'],s2)
        add('S3','A',new_prices['A'],s3a); add('S3','B',new_prices['B'],s3b); add('S3','C',new_prices['C'],s3c)
        cash -= 0.5*(leads_s1+leads_s2+leads_s3)
        comp=0; modeled_units=0
        for (g,p,price,bm),n in state.items():
            u=usage_base.get((g,p),120)*params.get('usage_mult',1.0)
            modeled_units += n*u
            comp += n*u*cost_per[p]
        comp*=max(0.55,random.gauss(1.0,params.get('compute_cv',0.07)))
        capacity=4000
        if params.get('allow_cap_down',False) and t>params.get('cap_down_after',49) and modeled_units < params.get('cap_down_avg_units',1900000):
            capacity=1330
        ops,dev=daily_spend(params,t,cash,modeled_units)
        cash -= capacity+ops+dev+comp
        if t%7==0: weekly.append(cash)
    return weekly

