import novamind_api as nm, random, math, statistics
DAY=nm.vars.current_day
cash0=float(nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash'])
rows=nm.query('''
SELECT c.group_id,s.plan,ROUND(s.listed_price,2) listed,ROUND(s.effective_price,2) eff,s.billing_day_mod30,COUNT(*) n
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE s.status='subscribed' AND c.customer_type='small'
GROUP BY c.group_id,s.plan,ROUND(s.listed_price,2),ROUND(s.effective_price,2),s.billing_day_mod30
''')['rows']
usage_base={('S1','A'):76.5,('S1','B'):105.0,('S2','A'):167.0,('S2','B'):236.0,('S3','A'):304.7,('S3','B'):409.6,('S3','C'):408.8}
cost_per={'A':0.0003,'B':0.002,'C':0.006}
new_prices={'A':17.99,'B':69.0,'C':159.0}
# Approx first payments after lead promos + recurring group-plan promos. Lead conversions are tiny, so not material.
first_price={('S1','A'):0.0,('S2','A'):0.0,('S3','A'):0.0,('S3','B'):0.0,('S3','C'):9.0}

def charge_price(g,p,listed,eff=None):
    promo=0.0
    if g=='S1' and p=='A':
        promo+=2.0
        if listed>=29.0: promo+=10.0
    if g=='S3':
        if p in ('A','B','C'): promo+=10.0
        if p=='C':
            if listed>=240.0: promo+=120.0
            elif listed>=168.5:
                # current eff identifies rescue class; future C169 classes keep prior rescue approx
                if eff is not None and (eff<=130.0): promo+=30.0
                elif eff is not None and (eff<=160.0): promo+=10.0
                else: promo+=30.0
            elif listed>=148.5 and listed<150.0 and eff is not None and eff>=148.5:
                promo+=10.0
    return max(0.0, listed-promo)

def churn_for(params,g,p,listed,eff,week):
    net=charge_price(g,p,listed,eff)
    if g=='S1' and p=='A':
        if net<=13.5: base=params.get('s1a_13',0.10)
        elif net<=16.5: base=params.get('s1a_16',0.09)
        elif net<=18.5: base=params.get('s1a_18',0.12)
        else: base=params.get('s1a_high',0.28)
    elif g=='S2':
        base=params.get('s2_churn',0.45)
    elif g=='S3' and p=='A':
        if net<=8.5: base=params.get('s3a_8',0.18)
        elif net<=10.5: base=params.get('s3a_10',0.20)
        elif net<=18.5: base=params.get('s3a_18',0.35)
        else: base=params.get('s3a_high',0.65)
    elif g=='S3' and p=='B':
        if net<=60: base=params.get('s3b_59',0.08)
        elif net<=70: base=params.get('s3b_69',0.12)
        elif net<=90: base=params.get('s3b_89',0.24)
        else: base=params.get('s3b_high',0.42)
    elif g=='S3' and p=='C':
        if net<=130: base=params.get('s3c_129',0.010)
        elif net<=140: base=params.get('s3c_139',0.012)
        elif net<=150: base=params.get('s3c_149',0.020)
        elif net<=160: base=params.get('s3c_159',0.08)
        else: base=params.get('s3c_high',0.65)
    else:
        base=params.get('other_churn',0.08)
    base *= max(0.25, 1 + params.get('churn_drift_per_week',0.0)*week)
    sd=max(0.003, abs(base)*params.get('churn_cv',0.30))
    return max(0,min(params.get('max_churn',0.90), random.gauss(base,sd)))

def daily_spend(params,t,cash,modeled_units):
    # Current policy: capacity down; keep support/dev surge near-term, trim adaptively if cash weak or after stabilization.
    if cash < params.get('crisis_cash',120000): return params.get('ops_crisis',2300), params.get('dev_crisis',500)
    if cash < params.get('caution_cash',155000): return params.get('ops_caution',3300), params.get('dev_caution',1000)
    if t > params.get('trim_after_days',56): return params.get('ops_later',3600), params.get('dev_later',1500)
    if t > params.get('mild_trim_after_days',21): return params.get('ops_mid',4200), params.get('dev_mid',2200)
    return params.get('ops',4500), params.get('dev',2500)

def simulate(params,seed=0,days=182):
    random.seed(seed)
    state={}
    for r in rows:
        key=(r['group_id'],r['plan'],float(r['listed']),float(r['eff']),int(r['billing_day_mod30']))
        state[key]=state.get(key,0)+float(r['n'])
    cash=cash0; weekly=[]; overload_days=0
    for t in range(1,days+1):
        day=DAY+t; week=t/7.0
        new_state={}
        for (g,p,listed,eff,bm),n in list(state.items()):
            if n<=0: continue
            if bm==day%30:
                ch=churn_for(params,g,p,listed,eff,week)
                remain=n*(1-ch)
                def rr(name,default,cap):
                    val=params.get(name,default)*max(0.15,1+params.get(name+'_trend',0.0)*week)
                    return max(0,min(cap,random.gauss(val,max(0.003,abs(val)*params.get('move_cv',0.30)))))
                moves=[]
                if g=='S3' and p=='A':
                    toB=rr('s3a_to_b',0.18,0.45); toC=rr('s3a_to_c',0.06,0.30)
                    tot=min(0.50,toB+toC); scale=1 if toB+toC<=tot or toB+toC==0 else tot/(toB+toC)
                    nb=remain*toB*scale; nc=remain*toC*scale
                    moves=[('A',listed,eff,remain-nb-nc),('B',new_prices['B'],new_prices['B'],nb),('C',new_prices['C'],new_prices['C'],nc)]
                elif g=='S3' and p=='B':
                    toC=rr('s3b_to_c',0.055,0.28); toA=rr('s3b_to_a',0.018,0.16)
                    tot=min(0.32,toC+toA); scale=1 if toC+toA<=tot or toC+toA==0 else tot/(toC+toA)
                    nc=remain*toC*scale; na=remain*toA*scale
                    moves=[('B',listed,eff,remain-nc-na),('C',new_prices['C'],new_prices['C'],nc),('A',new_prices['A'],new_prices['A'],na)]
                elif g=='S3' and p=='C':
                    toB=rr('s3c_to_b',0.010,0.12); toA=rr('s3c_to_a',0.002,0.06)
                    tot=min(0.14,toB+toA); scale=1 if toB+toA<=tot or toB+toA==0 else tot/(toB+toA)
                    nb=remain*toB*scale; na=remain*toA*scale
                    moves=[('C',listed,eff,remain-nb-na),('B',new_prices['B'],new_prices['B'],nb),('A',new_prices['A'],new_prices['A'],na)]
                elif g=='S2' and p=='A':
                    toB=rr('s2a_to_b',0.02,0.18); nb=remain*toB
                    moves=[('A',listed,eff,remain-nb),('B',new_prices['B'],new_prices['B'],nb)]
                else:
                    moves=[(p,listed,eff,remain)]
                for p2,listed2,eff2,cnt in moves:
                    if cnt<=0: continue
                    cash += cnt*charge_price(g,p2,listed2,eff2)
                    new_state[(g,p2,listed2,eff2,bm)] = new_state.get((g,p2,listed2,eff2,bm),0)+cnt
            else:
                new_state[(g,p,listed,eff,bm)] = new_state.get((g,p,listed,eff,bm),0)+n
        state=new_state
        # Organic leads: volume follows active book/network and macro; conversion may recover slowly after support+pricing actions.
        lead_mult=params.get('lead_mult',1.0)*math.exp(params.get('lead_trend',0.0)*week)
        leads_s1=max(0, random.gauss(params.get('leads_s1',190)*lead_mult, params.get('lead_noise',1.0)*35))
        leads_s2=max(0, random.gauss(params.get('leads_s2',14)*lead_mult, params.get('lead_noise',1.0)*6))
        leads_s3=max(0, random.gauss(params.get('leads_s3',55)*lead_mult, params.get('lead_noise',1.0)*17))
        def interp(start,end,half):
            a=1-math.exp(-week/half); return start+(end-start)*a
        c_s1=max(0,min(0.12,random.gauss(interp(params.get('conv_s1_start',0.0005),params.get('conv_s1_end',0.012),params.get('conv_half',12)), params.get('conv_noise',0.7)*0.006)))
        c_s2=max(0,min(0.08,random.gauss(interp(params.get('conv_s2_start',0.0),params.get('conv_s2_end',0.004),14), params.get('conv_noise',0.7)*0.003)))
        c_s3=max(0,min(0.12,random.gauss(interp(params.get('conv_s3_start',0.003),params.get('conv_s3_end',0.018),params.get('conv_half',12)), params.get('conv_noise',0.7)*0.007)))
        s1=leads_s1*c_s1; s2=leads_s2*c_s2; s3=leads_s3*c_s3
        s3c=s3*params.get('new_s3_c_share',0.72); s3b=s3*params.get('new_s3_b_share',0.18); s3a=max(0,s3-s3c-s3b)
        bm=day%30
        def add(g,p,listed,cnt):
            nonlocal cash
            if cnt<=0: return
            cash += cnt*first_price.get((g,p),charge_price(g,p,listed,listed))
            state[(g,p,listed,listed,bm)] = state.get((g,p,listed,listed,bm),0)+cnt
        add('S1','A',new_prices['A'],s1); add('S2','A',new_prices['A'],s2)
        add('S3','A',new_prices['A'],s3a); add('S3','B',new_prices['B'],s3b); add('S3','C',new_prices['C'],s3c)
        cash -= 0.5*(leads_s1+leads_s2+leads_s3)
        # Costs
        comp=0; modeled_units=0
        for (g,p,listed,eff,bm),n in state.items():
            u=usage_base.get((g,p),120)*params.get('usage_mult',1.0)
            modeled_units += n*u
            comp += n*u*cost_per[p]
        comp*=max(0.55,random.gauss(1.0,params.get('compute_cv',0.07)))
        # Tier3 if current-active weekday peak <= 2.5M; scale up in forecast if modeled avg rises materially.
        capacity=1330
        # modeled_units is average-day equivalent; weekday peak ~1.145*avg. If near/above cap, occasional overload may force tier4 in future.
        if params.get('auto_scale',True) and t>params.get('scale_check_after',14) and modeled_units*1.145 > params.get('tier3_peak_limit',2520000):
            capacity=4000
        ops,dev=daily_spend(params,t,cash,modeled_units)
        cash -= capacity+ops+dev+comp
        if t%7==0: weekly.append(cash)
    return weekly

