import novamind_api as nm, random, math, statistics, json
DAY=nm.vars.current_day
cash0=float(nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash'])
# Build initial state at post-action calculated renewal price (not current effective price).
promo=json.loads(nm.query("SELECT settings_json FROM config_overrides WHERE setting_type='promotion' ORDER BY day DESC,id DESC LIMIT 1")['rows'][0]['settings_json'])
bc={str(k):float(v) for k,v in (promo.get('by_customer') or {}).items()}; bgp=promo.get('by_group_plan') or {}; bg=promo.get('by_group') or {}; glob=float(promo.get('global') or 0)
rows=[]
mm=nm.query("SELECT MIN(customer_id) mn, MAX(customer_id) mx FROM subscriptions WHERE status='subscribed'")['rows'][0]
for lo in range(int(mm['mn'] or 0), int(mm['mx'] or 0)+1, 4000):
    rows += nm.query(f"""
    SELECT c.customer_id,c.group_id,s.plan,ROUND(s.listed_price,2) listed,s.billing_day_mod30
    FROM subscriptions s JOIN customers c USING(customer_id)
    WHERE s.status='subscribed' AND c.customer_type='small' AND s.customer_id BETWEEN {lo} AND {lo+3999}
    """)['rows']
init=[]
for r in rows:
    g=r['group_id']; p=r['plan']; listed=float(r['listed']); cid=str(r['customer_id'])
    pr=glob+float(bg.get(g,0) or 0)+float((bgp.get(g,{}) or {}).get(p,0) or 0)+float(bc.get(cid,0) or 0)
    price=max(0.0, listed-pr)
    init.append((g,p,round(price,2),int(r['billing_day_mod30'])))
# collapse
from collections import defaultdict
init_counts=defaultdict(float)
for x in init: init_counts[x]+=1

usage_base={('S1','A'):76.5,('S1','B'):75.0,('S2','A'):153.0,('S2','B'):232.0,('S3','A'):322.0,('S3','B'):396.0,('S3','C'):403.0}
cost_per={'A':0.0003,'B':0.0020,'C':0.0060}
# New/changed subscriptions do not get by-customer rescues until a future weekly rebuild; group-plan promos only.
def new_price(g,p):
    if g=='S1' and p=='A': return 15.99  # current list 17.99 - S1A group $2
    if g=='S3' and p=='A': return 7.99   # list 17.99 - $10
    if g=='S3' and p=='B': return 59.0   # list 69 - $10
    if g=='S3' and p=='C': return 129.0  # list 159 - $30
    if p=='A': return 17.99
    if p=='B': return 69.0
    return 159.0
first_price={('S1','A'):0.0,('S2','A'):0.0,('S3','A'):0.0,('S3','B'):0.0,('S3','C'):19.0}

def churn_for(params,g,p,price,week):
    # Monthly churn probability at billing. Calibrated to Day210 paid+canceled cohorts; rescued cohorts still carry some scar risk.
    if g=='S1' and p=='A':
        if price<=13.5: base=params.get('s1a_13',0.05)
        elif price<=16.5: base=params.get('s1a_16',0.075)
        elif price<=18.5: base=params.get('s1a_18',0.12)
        else: base=params.get('s1a_high',0.35)
    elif g=='S2':
        base=params.get('s2_churn',0.55)
    elif g=='S3' and p=='A':
        if price<=5.5: base=params.get('s3a_5',0.08)
        elif price<=8.5: base=params.get('s3a_8',0.28)
        elif price<=10.5: base=params.get('s3a_10',0.34)
        elif price<=20.5: base=params.get('s3a_20',0.45)
        else: base=params.get('s3a_high',0.75)
    elif g=='S3' and p=='B':
        if price<=60: base=params.get('s3b_59',0.045)
        elif price<=70: base=params.get('s3b_69',0.10)
        elif price<=90: base=params.get('s3b_89',0.12)
        elif price<=110: base=params.get('s3b_109',0.16)
        else: base=params.get('s3b_high',0.45)
    elif g=='S3' and p=='C':
        if price<=120: base=params.get('s3c_119',0.045)
        elif price<=130: base=params.get('s3c_129',0.06)
        elif price<=140: base=params.get('s3c_139',0.10)
        elif price<=150: base=params.get('s3c_149',0.18)
        else: base=params.get('s3c_high',0.65)
    else:
        base=params.get('other_churn',0.12)
    # If support fixes stick, scar churn decays slightly; competitor pressure adds slow drift.
    decay=1.0 - params.get('support_decay',0.10)*(1-math.exp(-week/8.0))
    drift=1.0 + params.get('churn_drift_per_week',0.002)*week
    base=max(0.002, base*decay*drift)
    sd=max(0.002, abs(base)*params.get('churn_cv',0.35))
    return max(0,min(params.get('max_churn',0.92), random.gauss(base,sd)))

def daily_spend(params,t,cash):
    # We intend to keep the Day210 support push for a few weeks, then trim if social/issue aging improves; cut harder if cash weakens.
    if cash < params.get('crisis_cash',105000): return params.get('ops_crisis',1600), params.get('dev_crisis',200)
    if cash < params.get('caution_cash',145000): return params.get('ops_caution',2800), params.get('dev_caution',600)
    if t > params.get('trim2_after_days',98): return params.get('ops_later2',2800), params.get('dev_later2',500)
    if t > params.get('trim_after_days',35): return params.get('ops_later',3400), params.get('dev_later',900)
    return params.get('ops',4100), params.get('dev',1500)

def simulate(params,seed=0,days=182):
    random.seed(seed)
    state=dict(init_counts)
    cash=cash0; weekly=[]; tier4_days=0
    for t in range(1,days+1):
        day=DAY+t; week=t/7.0
        new_state=defaultdict(float)
        # billing
        for (g,p,price,bm),n in list(state.items()):
            if n<=0: continue
            if bm==day%30:
                ch=churn_for(params,g,p,price,week)
                remain=n*(1-ch)
                def rr(name,default,cap):
                    val=params.get(name,default)*max(0.10,1+params.get(name+'_trend',0.0)*week)
                    return max(0,min(cap,random.gauss(val,max(0.002,abs(val)*params.get('move_cv',0.30)))))
                moves=[]
                if g=='S3' and p=='A':
                    toB=rr('s3a_to_b',0.10,0.38); toC=rr('s3a_to_c',0.025,0.18); tot=min(0.42,toB+toC); sc=1 if toB+toC<=tot or toB+toC==0 else tot/(toB+toC)
                    nb=remain*toB*sc; nc=remain*toC*sc; moves=[('A',price,remain-nb-nc),('B',new_price(g,'B'),nb),('C',new_price(g,'C'),nc)]
                elif g=='S3' and p=='B':
                    toC=rr('s3b_to_c',0.030,0.18); toA=rr('s3b_to_a',0.018,0.12); tot=min(0.25,toC+toA); sc=1 if toC+toA<=tot or toC+toA==0 else tot/(toC+toA)
                    nc=remain*toC*sc; na=remain*toA*sc; moves=[('B',price,remain-nc-na),('C',new_price(g,'C'),nc),('A',new_price(g,'A'),na)]
                elif g=='S3' and p=='C':
                    toB=rr('s3c_to_b',0.010,0.08); toA=rr('s3c_to_a',0.002,0.035); tot=min(0.10,toB+toA); sc=1 if toB+toA<=tot or toB+toA==0 else tot/(toB+toA)
                    nb=remain*toB*sc; na=remain*toA*sc; moves=[('C',price,remain-nb-na),('B',new_price(g,'B'),nb),('A',new_price(g,'A'),na)]
                elif g=='S2' and p=='A':
                    toB=rr('s2a_to_b',0.015,0.12); nb=remain*toB; moves=[('A',price,remain-nb),('B',new_price(g,'B'),nb)]
                else:
                    moves=[(p,price,remain)]
                for p2,price2,cnt in moves:
                    if cnt<=0: continue
                    cash += cnt*price2
                    new_state[(g,p2,round(price2,2),bm)] += cnt
            else:
                new_state[(g,p,price,bm)] += n
        state=new_state
        # Organic/network leads; mostly lost but cost incurred. Only S3 C converts materially.
        lead_mult=params.get('lead_mult',1.0)*math.exp(params.get('lead_trend',0.0)*week)
        leads_s1=max(0, random.gauss(params.get('leads_s1',190)*lead_mult, params.get('lead_noise',1.0)*35))
        leads_s2=max(0, random.gauss(params.get('leads_s2',16)*lead_mult, params.get('lead_noise',1.0)*6))
        leads_s3=max(0, random.gauss(params.get('leads_s3',50)*lead_mult, params.get('lead_noise',1.0)*16))
        def approach(start,end,half):
            a=1-math.exp(-week/half); return start+(end-start)*a
        c_s1=max(0,min(0.03,random.gauss(approach(params.get('conv_s1_start',0.0),params.get('conv_s1_end',0.003),params.get('conv_half',12)), params.get('conv_noise',0.7)*0.003)))
        c_s2=max(0,min(0.02,random.gauss(approach(params.get('conv_s2_start',0.0),params.get('conv_s2_end',0.0015),14), params.get('conv_noise',0.7)*0.0015)))
        c_s3=max(0,min(0.08,random.gauss(approach(params.get('conv_s3_start',0.020),params.get('conv_s3_end',0.035),params.get('conv_half',12)), params.get('conv_noise',0.7)*0.012)))
        s1=leads_s1*c_s1; s2=leads_s2*c_s2; s3=leads_s3*c_s3
        s3c=s3*params.get('new_s3_c_share',0.92); s3b=s3*params.get('new_s3_b_share',0.04); s3a=max(0,s3-s3c-s3b)
        bm=day%30
        def add(g,p,cnt):
            nonlocal cash
            if cnt<=0: return
            price=new_price(g,p)
            cash += cnt*first_price.get((g,p),price)
            state[(g,p,round(price,2),bm)] += cnt
        add('S1','A',s1); add('S2','A',s2); add('S3','A',s3a); add('S3','B',s3b); add('S3','C',s3c)
        cash -= 0.5*(leads_s1+leads_s2+leads_s3)
        # Costs
        modeled_units=0; comp=0
        for (g,p,price,bm),n in state.items():
            u=usage_base.get((g,p),120)*params.get('usage_mult',1.0)
            modeled_units += n*u
            comp += n*u*cost_per[p]
        comp*=max(0.55,random.gauss(1.0,params.get('compute_cv',0.08)))
        # Tier3 unless modeled weekday peak risks overload; tier4 only if absolutely needed.
        capacity=1330
        if params.get('auto_scale',True) and t>params.get('scale_check_after',14) and modeled_units*params.get('peak_factor',1.28)>params.get('tier3_peak_limit',2500000):
            capacity=4000; tier4_days+=1
        ops,dev=daily_spend(params,t,cash)
        cash -= capacity+ops+dev+comp
        if t%7==0: weekly.append(cash)
    return weekly

