import novamind_api as nm, random, math, statistics, json
from collections import defaultdict
DAY=nm.vars.current_day
cash0=float(nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash'])
# Initial state at post-action renewal prices from current promotion override (active subscriptions chunked).
promo=json.loads(nm.query("SELECT settings_json FROM config_overrides WHERE setting_type='promotion' ORDER BY id DESC LIMIT 1")['rows'][0]['settings_json'])
bc={str(k):float(v) for k,v in (promo.get('by_customer') or {}).items()}; bgp=promo.get('by_group_plan') or {}; bg=promo.get('by_group') or {}; glob=float(promo.get('global') or 0)
rows=[]
mm=nm.query("SELECT MIN(customer_id) mn, MAX(customer_id) mx FROM subscriptions WHERE status='subscribed'")['rows'][0]
for lo in range(int(mm['mn'] or 0), int(mm['mx'] or 0)+1, 4000):
    rows += nm.query(f"""
    SELECT c.customer_id,c.group_id,s.plan,ROUND(s.listed_price,2) listed,s.billing_day_mod30
    FROM subscriptions s JOIN customers c USING(customer_id)
    WHERE s.status='subscribed' AND c.customer_type='small' AND s.customer_id BETWEEN {lo} AND {lo+3999}
    """)['rows']
init_counts=defaultdict(float)
for r in rows:
    g=r['group_id']; p=r['plan']; listed=float(r['listed']); cid=str(r['customer_id'])
    pr=glob+float(bg.get(g,0) or 0)+float((bgp.get(g,{}) or {}).get(p,0) or 0)+float(bc.get(cid,0) or 0)
    price=max(0.0, listed-pr)
    init_counts[(g,p,round(price,2),int(r['billing_day_mod30']))]+=1

usage_base={('S1','A'):77.2,('S1','B'):63.5,('S2','A'):148.5,('S2','B'):180.6,('S3','A'):315.9,('S3','B'):389.9,('S3','C'):410.6}
cost_per={'A':0.0003,'B':0.0020,'C':0.0060}
# Future movers/new subscribers get current group-plan target, with weekly rebuild assumed to catch S3 C rescue before renewal.
def new_price(g,p):
    if g=='S1' and p=='A': return 15.99
    if g=='S3' and p=='A': return 7.99
    if g=='S3' and p=='B': return 59.0
    if g=='S3' and p=='C': return 109.0
    if p=='A': return 17.99
    if p=='B': return 69.0
    return 159.0
# Lead promotions mean first billing is usually zero for organic S1/S3 trials; subscriptions bill on renewal later.
first_price={('S1','A'):0.0,('S2','A'):0.0,('S3','A'):0.0,('S3','B'):0.0,('S3','C'):0.0}

def churn_for(params,g,p,price,week):
    # Monthly churn at billing. Calibrated to D225-231 paid+canceled after support/discount tests.
    if g=='S1' and p=='A':
        if price<=13.5: base=params.get('s1a_13',0.18)
        elif price<=16.5: base=params.get('s1a_16',0.21)
        elif price<=18.5: base=params.get('s1a_18',0.24)
        else: base=params.get('s1a_high',0.42)
    elif g=='S2':
        base=params.get('s2_churn',0.55)
    elif g=='S3' and p=='A':
        if price<=5.5: base=params.get('s3a_5',0.35)
        elif price<=8.5: base=params.get('s3a_8',0.44)
        elif price<=10.5: base=params.get('s3a_10',0.53)
        elif price<=20.5: base=params.get('s3a_20',0.62)
        else: base=params.get('s3a_high',0.82)
    elif g=='S3' and p=='B':
        if price<=45.5: base=params.get('s3b_39',0.12)
        elif price<=50.5: base=params.get('s3b_49',0.17)
        elif price<=60.5: base=params.get('s3b_59',0.24)
        elif price<=70.5: base=params.get('s3b_69',0.28)
        elif price<=90.5: base=params.get('s3b_89',0.34)
        elif price<=110.5: base=params.get('s3b_109',0.42)
        else: base=params.get('s3b_high',0.64)
    elif g=='S3' and p=='C':
        if price<=110.5: base=params.get('s3c_109',0.085)
        elif price<=120.5: base=params.get('s3c_119',0.12)
        elif price<=130.5: base=params.get('s3c_129',0.17)
        elif price<=140.5: base=params.get('s3c_139',0.24)
        elif price<=150.5: base=params.get('s3c_149',0.38)
        else: base=params.get('s3c_high',0.72)
    else:
        base=params.get('other_churn',0.15)
    # Support ops/social may reduce scar churn gradually; competitor drift can offset it.
    decay=1.0 - params.get('support_decay',0.10)*(1-math.exp(-week/7.0))
    drift=1.0 + params.get('churn_drift_per_week',0.003)*week
    base=max(0.002, base*decay*drift)
    sd=max(0.002, abs(base)*params.get('churn_cv',0.36))
    return max(0,min(params.get('max_churn',0.94), random.gauss(base,sd)))

def daily_spend(params,t,cash):
    # Post-D231: ops 3800/dev 600, then planned gradual trims if support stabilizes; crisis cuts if cash falls.
    if cash < params.get('crisis_cash',95000): return params.get('ops_crisis',1200), params.get('dev_crisis',75)
    if cash < params.get('caution_cash',130000): return params.get('ops_caution',2200), params.get('dev_caution',200)
    if t > params.get('trim2_after_days',91): return params.get('ops_later2',2200), params.get('dev_later2',150)
    if t > params.get('trim_after_days',35): return params.get('ops_later',3000), params.get('dev_later',350)
    return params.get('ops',3800), params.get('dev',600)

def simulate(params,seed=0,days=182):
    random.seed(seed)
    state=dict(init_counts)
    cash=cash0; weekly=[]; tier4_days=0
    for t in range(1,days+1):
        day=DAY+t; week=t/7.0
        new_state=defaultdict(float)
        # bill renewals and plan changes
        for (g,p,price,bm),n in list(state.items()):
            if n<=0: continue
            if bm==day%30:
                ch=churn_for(params,g,p,price,week)
                remain=n*(1-ch)
                def rr(name,default,cap):
                    val=params.get(name,default)*max(0.10,1+params.get(name+'_trend',0.0)*week)
                    return max(0,min(cap,random.gauss(val,max(0.002,abs(val)*params.get('move_cv',0.32)))))
                if g=='S3' and p=='A':
                    toB=rr('s3a_to_b',0.08,0.34); toC=rr('s3a_to_c',0.018,0.16); tot=min(0.40,toB+toC); sc=1 if toB+toC<=tot or toB+toC==0 else tot/(toB+toC)
                    nb=remain*toB*sc; nc=remain*toC*sc; moves=[('A',price,remain-nb-nc),('B',new_price(g,'B'),nb),('C',new_price(g,'C'),nc)]
                elif g=='S3' and p=='B':
                    toC=rr('s3b_to_c',0.020,0.16); toA=rr('s3b_to_a',0.032,0.14); tot=min(0.26,toC+toA); sc=1 if toC+toA<=tot or toC+toA==0 else tot/(toC+toA)
                    nc=remain*toC*sc; na=remain*toA*sc; moves=[('B',price,remain-nc-na),('C',new_price(g,'C'),nc),('A',new_price(g,'A'),na)]
                elif g=='S3' and p=='C':
                    toB=rr('s3c_to_b',0.016,0.10); toA=rr('s3c_to_a',0.004,0.04); tot=min(0.12,toB+toA); sc=1 if toB+toA<=tot or toB+toA==0 else tot/(toB+toA)
                    nb=remain*toB*sc; na=remain*toA*sc; moves=[('C',price,remain-nb-na),('B',new_price(g,'B'),nb),('A',new_price(g,'A'),na)]
                elif g=='S2' and p=='A':
                    toB=rr('s2a_to_b',0.012,0.12); nb=remain*toB; moves=[('A',price,remain-nb),('B',new_price(g,'B'),nb)]
                else:
                    moves=[(p,price,remain)]
                for p2,price2,cnt in moves:
                    if cnt<=0: continue
                    cash += cnt*price2
                    new_state[(g,p2,round(price2,2),bm)] += cnt
            else:
                new_state[(g,p,price,bm)] += n
        state=new_state
        # organic/network leads: mostly lost; tiny S3 C conversion, lead cost incurred.
        lead_mult=params.get('lead_mult',1.0)*math.exp(params.get('lead_trend',0.0)*week)
        leads_s1=max(0, random.gauss(params.get('leads_s1',170)*lead_mult, params.get('lead_noise',1.0)*35))
        leads_s2=max(0, random.gauss(params.get('leads_s2',10)*lead_mult, params.get('lead_noise',1.0)*5))
        leads_s3=max(0, random.gauss(params.get('leads_s3',42)*lead_mult, params.get('lead_noise',1.0)*15))
        def approach(start,end,half):
            a=1-math.exp(-week/half); return start+(end-start)*a
        c_s1=max(0,min(0.02,random.gauss(approach(params.get('conv_s1_start',0.0),params.get('conv_s1_end',0.0012),params.get('conv_half',12)), params.get('conv_noise',0.8)*0.002)))
        c_s2=max(0,min(0.015,random.gauss(approach(params.get('conv_s2_start',0.0),params.get('conv_s2_end',0.0007),14), params.get('conv_noise',0.8)*0.001)))
        c_s3=max(0,min(0.07,random.gauss(approach(params.get('conv_s3_start',0.016),params.get('conv_s3_end',0.026),params.get('conv_half',12)), params.get('conv_noise',0.8)*0.010)))
        s1=leads_s1*c_s1; s2=leads_s2*c_s2; s3=leads_s3*c_s3
        s3c=s3*params.get('new_s3_c_share',0.92); s3b=s3*params.get('new_s3_b_share',0.04); s3a=max(0,s3-s3c-s3b)
        bm=day%30
        def add(g,p,cnt):
            nonlocal cash
            if cnt<=0: return
            price=new_price(g,p)
            cash += cnt*first_price.get((g,p),price)
            state[(g,p,round(price,2),bm)] += cnt
        add('S1','A',s1); add('S2','A',s2); add('S3','A',s3a); add('S3','B',s3b); add('S3','C',s3c)
        cash -= 0.5*(leads_s1+leads_s2+leads_s3)
        # Costs based on active state; tier3 unless peak model demands tier4.
        modeled_units=0; comp=0
        for (g,p,price,bm),n in state.items():
            u=usage_base.get((g,p),120)*params.get('usage_mult',1.0)
            modeled_units += n*u
            comp += n*u*cost_per[p]
        comp*=max(0.55,random.gauss(1.0,params.get('compute_cv',0.08)))
        capacity=1330
        if params.get('auto_scale',True) and t>params.get('scale_check_after',14) and modeled_units*params.get('peak_factor',1.28)>params.get('tier3_peak_limit',2500000):
            capacity=4000; tier4_days+=1
        ops,dev=daily_spend(params,t,cash)
        cash -= capacity+ops+dev+comp
        if t%7==0: weekly.append(cash)
    return weekly

