import novamind_api as nm, random, math, statistics, json
from collections import defaultdict
DAY=nm.vars.current_day
cash0=float(nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash'])
# load current target prices from promotion override
promo=json.loads(nm.query("SELECT settings_json FROM config_overrides WHERE setting_type='promotion' ORDER BY id DESC LIMIT 1")['rows'][0]['settings_json'])
bc={str(k):float(v) for k,v in (promo.get('by_customer') or {}).items()}; bgp=promo.get('by_group_plan') or {}; bg=promo.get('by_group') or {}; glob=float(promo.get('global') or 0)
rows=[]
mm=nm.query("SELECT MIN(customer_id) mn, MAX(customer_id) mx FROM subscriptions WHERE status='subscribed'")['rows'][0]
for lo in range(int(mm['mn'] or 0), int(mm['mx'] or 0)+1, 3500):
    rows += nm.query(f"""
    SELECT c.customer_id,c.group_id,s.plan,ROUND(s.listed_price,2) listed,s.billing_day_mod30
    FROM subscriptions s JOIN customers c USING(customer_id)
    WHERE s.status='subscribed' AND c.customer_type='small' AND s.customer_id BETWEEN {lo} AND {lo+3499}
    """)['rows']
init_counts=defaultdict(float)
for r in rows:
    g=r['group_id']; p=r['plan']; listed=float(r['listed']); cid=str(r['customer_id'])
    pr=glob+float(bg.get(g,0) or 0)+float((bgp.get(g,{}) or {}).get(p,0) or 0)+float(bc.get(cid,0) or 0)
    price=round(max(0.0, listed-pr),2)
    init_counts[(g,p,price,int(r['billing_day_mod30']))]+=1

usage_base={('S1','A'):77.1,('S1','B'):56.3,('S2','A'):149.8,('S2','B'):180.6,('S3','A'):316.4,('S3','B'):394.4,('S3','C'):413.2}
cost_per={'A':0.0003,'B':0.0020,'C':0.0060}
# current public prices for future subscribers / plan changes after day238
public_price={'A':12.99,'B':49.0,'C':99.0}

def new_price(g,p):
    # In future weekly rebuilds I expect to keep the same target ladder for active customers.
    if g=='S1' and p=='A': return 12.99
    if g=='S3' and p=='A': return 7.99
    if g=='S3' and p=='B': return 49.0
    if g=='S3' and p=='C': return 99.0
    return public_price[p]
first_price={('S1','A'):9.99,('S2','A'):12.99,('S3','A'):0.0,('S3','B'):29.0,('S3','C'):79.0}

def churn_for(params,g,p,price,week):
    # Monthly churn at billing, recalibrated after D234-D238 competitor shock (observed 40-90% churn in many cohorts).
    if g=='S1' and p=='A':
        if price<=10.5: base=params.get('s1a_10',0.50)
        elif price<=13.5: base=params.get('s1a_13',0.48)
        elif price<=16.5: base=params.get('s1a_16',0.58)
        else: base=params.get('s1a_high',0.80)
    elif g=='S2':
        base=params.get('s2_churn',0.72)
    elif g=='S3' and p=='A':
        if price<=5.5: base=params.get('s3a_5',0.70)
        elif price<=8.5: base=params.get('s3a_8',0.76)
        elif price<=10.5: base=params.get('s3a_10',0.82)
        else: base=params.get('s3a_high',0.90)
    elif g=='S3' and p=='B':
        if price<=40.5: base=params.get('s3b_39',0.42)
        elif price<=50.5: base=params.get('s3b_49',0.44)
        elif price<=60.5: base=params.get('s3b_59',0.55)
        elif price<=70.5: base=params.get('s3b_69',0.65)
        else: base=params.get('s3b_high',0.78)
    elif g=='S3' and p=='C':
        if price<=90.5: base=params.get('s3c_89',0.30)
        elif price<=100.5: base=params.get('s3c_99',0.34)
        elif price<=110.5: base=params.get('s3c_109',0.43)
        elif price<=120.5: base=params.get('s3c_119',0.52)
        else: base=params.get('s3c_high',0.72)
    else:
        base=params.get('other_churn',0.35)
    # Some shock decay if public price/support message works; offset by ongoing competitor drift/outage risk.
    decay=1.0 - params.get('shock_decay',0.10)*(1-math.exp(-week/5.0))
    drift=1.0 + params.get('churn_drift_per_week',0.006)*week
    base=max(0.01,base*decay*drift)
    sd=max(0.01,abs(base)*params.get('churn_cv',0.28))
    return max(0,min(params.get('max_churn',0.97), random.gauss(base,sd)))

def daily_spend(params,t,cash):
    # Current week set 2600 ops / 400 dev. Future rational crisis cuts are assumed if cash falls.
    if cash < params.get('desperation_cash',65000):
        return params.get('ops_desperation',500), params.get('dev_desperation',0)
    if cash < params.get('crisis_cash',95000):
        return params.get('ops_crisis',1000), params.get('dev_crisis',50)
    if cash < params.get('caution_cash',120000):
        return params.get('ops_caution',1600), params.get('dev_caution',100)
    if t>params.get('cut_after_days',35):
        return params.get('ops_later',1600), params.get('dev_later',100)
    return params.get('ops',2600), params.get('dev',400)

def cap_cost(params, modeled_units, t):
    # modeled_units is average daily units; need headroom for peaks. Downscale only when safely below tier2.
    peak=modeled_units*params.get('peak_factor',1.35)
    if t>params.get('downscale_after',14) and peak < params.get('tier2_safe_peak',740000):
        return 530
    return 1330

def simulate(params,seed=0,days=182):
    random.seed(seed)
    state=dict(init_counts); cash=cash0; weekly=[]
    for t in range(1,days+1):
        day=DAY+t; week=t/7.0
        new_state=defaultdict(float)
        for (g,p,price,bm),n in list(state.items()):
            if n<=0: continue
            if bm==day%30:
                ch=churn_for(params,g,p,price,week)
                remain=n*(1-ch)
                # plan moves: include a few downgrades/upgrades among survivors
                def rr(name,default,cap):
                    val=max(0,min(cap,random.gauss(params.get(name,default), max(0.001,params.get(name,default)*params.get('move_cv',0.35)))))
                    return val
                moves=[(p,price,remain)]
                if g=='S3' and p=='A':
                    toB=rr('s3a_to_b',0.04,0.25); toC=rr('s3a_to_c',0.008,0.08); sc=min(1,0.30/max(1e-9,toB+toC))
                    nb=remain*toB*sc; nc=remain*toC*sc; moves=[('A',price,remain-nb-nc),('B',new_price(g,'B'),nb),('C',new_price(g,'C'),nc)]
                elif g=='S3' and p=='B':
                    toC=rr('s3b_to_c',0.010,0.08); toA=rr('s3b_to_a',0.045,0.18); sc=min(1,0.22/max(1e-9,toC+toA))
                    nc=remain*toC*sc; na=remain*toA*sc; moves=[('B',price,remain-nc-na),('C',new_price(g,'C'),nc),('A',new_price(g,'A'),na)]
                elif g=='S3' and p=='C':
                    toB=rr('s3c_to_b',0.025,0.12); toA=rr('s3c_to_a',0.006,0.04); sc=min(1,0.14/max(1e-9,toB+toA))
                    nb=remain*toB*sc; na=remain*toA*sc; moves=[('C',price,remain-nb-na),('B',new_price(g,'B'),nb),('A',new_price(g,'A'),na)]
                for p2,price2,cnt in moves:
                    if cnt<=0: continue
                    cash += cnt*price2
                    new_state[(g,p2,round(price2,2),bm)] += cnt
            else:
                new_state[(g,p,price,bm)] += n
        state=new_state
        # organic/network leads, mostly lost after reputation/quality shock
        lead_mult=max(0.2, params.get('lead_mult',1.0)*math.exp(params.get('lead_trend',-0.01)*week))
        leads_s1=max(0, random.gauss(params.get('leads_s1',170)*lead_mult, params.get('lead_noise',1.0)*35))
        leads_s2=max(0, random.gauss(params.get('leads_s2',10)*lead_mult, params.get('lead_noise',1.0)*5))
        leads_s3=max(0, random.gauss(params.get('leads_s3',42)*lead_mult, params.get('lead_noise',1.0)*15))
        c_s1=max(0,min(0.02,random.gauss(params.get('conv_s1',0.0015), params.get('conv_noise',1.0)*0.0015)))
        c_s2=max(0,min(0.01,random.gauss(params.get('conv_s2',0.0003), params.get('conv_noise',1.0)*0.0007)))
        c_s3=max(0,min(0.05,random.gauss(params.get('conv_s3',0.010), params.get('conv_noise',1.0)*0.006)))
        s1=leads_s1*c_s1; s2=leads_s2*c_s2; s3=leads_s3*c_s3
        s3c=s3*params.get('new_s3_c_share',0.85); s3b=s3*0.10; s3a=max(0,s3-s3c-s3b)
        bm=day%30
        def add(g,p,cnt):
            nonlocal cash
            if cnt<=0: return
            price=new_price(g,p)
            cash += cnt*first_price.get((g,p),price)
            state[(g,p,round(price,2),bm)] += cnt
        add('S1','A',s1); add('S2','A',s2); add('S3','A',s3a); add('S3','B',s3b); add('S3','C',s3c)
        cash -= 0.5*(leads_s1+leads_s2+leads_s3)
        # costs
        modeled_units=0; comp=0
        for (g,p,price,bm),n in state.items():
            u=usage_base.get((g,p),120)*params.get('usage_mult',1.0)
            modeled_units += n*u
            comp += n*u*cost_per[p]
        comp=max(0,comp*random.gauss(1.0,params.get('compute_cv',0.09)))
        capacity=cap_cost(params,modeled_units,t)
        ops,dev=daily_spend(params,t,cash)
        cash -= capacity+ops+dev+comp
        if t%7==0: weekly.append(cash)
    return weekly

