def churn_for(params,g,p,price,week,c_tier2=False):
    # Monthly cancellation probability at billing, calibrated to D239-D245 target-price retention.
    if g=='S1' and p=='A':
        if price<=10.5: base=params.get('s1a_10',0.62)
        elif price<=13.5: base=params.get('s1a_13',0.72)
        elif price<=16.5: base=params.get('s1a_16',0.82)
        else: base=params.get('s1a_high',0.92)
    elif g=='S2':
        base=params.get('s2_churn',0.90)
    elif g=='S3' and p=='A':
        base=params.get('s3a',0.96)
    elif g=='S3' and p=='B':
        if price<=40.5: base=params.get('s3b_39',0.55)
        elif price<=50.5: base=params.get('s3b_49',0.68)
        elif price<=60.5: base=params.get('s3b_59',0.78)
        else: base=params.get('s3b_high',0.88)
    elif g=='S3' and p=='C':
        if c_tier2:
            base=params.get('s3c_99_tier2_churn',0.50)
        elif price<=80.5:
            base=params.get('s3c_low',0.08)
        elif price<=100.5:
            base=params.get('s3c_99',0.16)
        elif price<=120.5:
            base=params.get('s3c_119',0.55)
        else:
            base=params.get('s3c_high',0.80)
    else:
        base=params.get('other_churn',0.50)
    # support cut and competitor drift can worsen; post/social and price reset may decay shock.
    decay=1.0 - params.get('shock_decay',0.02)*(1-math.exp(-week/6.0))
    drift=1.0 + params.get('churn_drift_per_week',0.010)*week
    base=max(0.01,base*decay*drift)
    sd=max(0.01,abs(base)*params.get('churn_cv',0.22))
    return max(0,min(params.get('max_churn',0.99),random.gauss(base,sd)))

def spend_for(params,t,cash):
    # Week 36 starts at ops 1450 / dev 100. Later weekly crisis cuts if cash keeps falling.
    if cash < params.get('desperation_cash',65000):
        return params.get('ops_desperation',150), params.get('dev_desperation',0)
    if cash < params.get('crisis_cash',90000):
        return params.get('ops_crisis',500), params.get('dev_crisis',0)
    if cash < params.get('caution_cash',120000):
        return params.get('ops_caution',900), params.get('dev_caution',0)
    return params.get('ops',1450), params.get('dev',100)

def maybe_c_tier2(params,t,cash):
    # Future hard compute cut: not taken this week, but likely if cash weak after collecting most current C renewals.
    after=params.get('c_tier2_after_days',9999)
    return t>=after or (t>=params.get('c_tier2_cash_after_days',42) and cash<params.get('c_tier2_cash',85000))

def capacity_cost(params,modeled_units,t):
    # Downscale only after churn makes peaks safe. Keep tier3 initially.
    peak=modeled_units*params.get('peak_factor',1.35)
    if t>=params.get('tier2_after_days',21) and peak<params.get('tier2_safe_peak',760000):
        return 530
    return 1330

def simulate(params,seed=0,days=182):
    random.seed(seed)
    state=defaultdict(float, init_counts)
    cash=cash0
    weekly=[]
    c_tier2=False
    for t in range(1,days+1):
        day=DAY+t; week=t/7.0
        c_tier2 = c_tier2 or maybe_c_tier2(params,t,cash)
        new_state=defaultdict(float)
        # billing/re-evaluation
        for (g,p,price,bm),n in list(state.items()):
            if n<=0: continue
            if bm==day%30:
                ch=churn_for(params,g,p,price,week,c_tier2=(c_tier2 and p=='C'))
                remain=n*(1-ch)
                # Plan changes: distressed lower-tier segments mostly cancel; C may downgrade if C tier becomes same model as B.
                moves=[(p,price,remain)]
                def gauss_rate(name,default,cap):
                    val=random.gauss(params.get(name,default), max(0.001,params.get(name,default)*params.get('move_cv',0.35)))
                    return max(0,min(cap,val))
                if g=='S3' and p=='C':
                    if c_tier2:
                        toB=gauss_rate('s3c_tier2_to_b',0.35,0.80); toA=gauss_rate('s3c_tier2_to_a',0.03,0.10)
                    else:
                        toB=gauss_rate('s3c_to_b',0.025,0.15); toA=gauss_rate('s3c_to_a',0.004,0.04)
                    sc=min(1,0.85/max(1e-9,toB+toA))
                    nb=remain*toB*sc; na=remain*toA*sc
                    moves=[('C',target_price(g,'C'),remain-nb-na),('B',target_price(g,'B'),nb),('A',target_price(g,'A'),na)]
                elif g=='S3' and p=='B':
                    toA=gauss_rate('s3b_to_a',0.05,0.20); toC=gauss_rate('s3b_to_c',0.008,0.06)
                    sc=min(1,0.25/max(1e-9,toA+toC)); na=remain*toA*sc; nc=remain*toC*sc
                    moves=[('B',target_price(g,'B'),remain-na-nc),('A',target_price(g,'A'),na),('C',target_price(g,'C'),nc)]
                elif g=='S3' and p=='A':
                    # rare survivors may upgrade.
                    toB=gauss_rate('s3a_to_b',0.02,0.10); toC=gauss_rate('s3a_to_c',0.002,0.03)
                    nb=remain*toB; nc=remain*toC
                    moves=[('A',target_price(g,'A'),remain-nb-nc),('B',target_price(g,'B'),nb),('C',target_price(g,'C'),nc)]
                for p2,price2,cnt in moves:
                    if cnt<=0: continue
                    cash += cnt*price2
                    new_state[(g,p2,round(price2,2),bm)] += cnt
            else:
                new_state[(g,p,price,bm)] += n
        state=new_state
        # organic network leads: current conversion was zero; S1 first-month promo may rescue a few.
        lead_scale=max(0.15,params.get('lead_scale',1.0)*math.exp(params.get('lead_trend',-0.03)*week))
        leads_s1=max(0,random.gauss(params.get('leads_s1',130)*lead_scale, params.get('lead_noise',1.0)*35))
        leads_s2=max(0,random.gauss(params.get('leads_s2',9)*lead_scale, params.get('lead_noise',1.0)*5))
        leads_s3=max(0,random.gauss(params.get('leads_s3',34)*lead_scale, params.get('lead_noise',1.0)*16))
        cs1=max(0,min(0.04,random.gauss(params.get('conv_s1',0.004), params.get('conv_noise',1.0)*0.003)))
        cs2=max(0,min(0.01,random.gauss(params.get('conv_s2',0.0), params.get('conv_noise',1.0)*0.001)))
        cs3=max(0,min(0.03,random.gauss(params.get('conv_s3',0.002), params.get('conv_noise',1.0)*0.003)))
        n_s1=leads_s1*cs1; n_s2=leads_s2*cs2; n_s3=leads_s3*cs3
        # S3 new conversions if any skew to C/B due lead promo, but stay tiny.
        additions=[('S1','A',n_s1),('S2','A',n_s2),('S3','C',n_s3*0.70),('S3','B',n_s3*0.25),('S3','A',n_s3*0.05)]
        bm=day%30
        for g,p,cnt in additions:
            if cnt<=0: continue
            cash += cnt*first_price.get((g,p),target_price(g,p))
            state[(g,p,round(target_price(g,p),2),bm)] += cnt
        cash -= 0.5*(leads_s1+leads_s2+leads_s3)
        # costs
        cost_per={'A':0.0003,'B':0.0020,'C':(0.0020 if c_tier2 else 0.0060)}
        modeled_units=0.0; comp=0.0
        for (g,p,price,bm),n in state.items():
            u=usage_base.get((g,p),150.0)*params.get('usage_mult',1.0)
            modeled_units += n*u
            comp += n*u*cost_per[p]
        comp=max(0,comp*random.gauss(1.0,params.get('compute_cv',0.10)))
        cap=capacity_cost(params,modeled_units,t)
        ops,dev=spend_for(params,t,cash)
        cash -= (cap+ops+dev+comp)
        if t%7==0:
            weekly.append(cash)
    return weekly

