import novamind_api as nm, random, math, statistics, json
from collections import defaultdict
DAY=nm.vars.current_day
cash0=float(nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash'])
promo=json.loads(nm.query("SELECT settings_json FROM config_overrides WHERE setting_type='promotion' ORDER BY id DESC LIMIT 1")['rows'][0]['settings_json'])
bc={str(k):float(v) for k,v in (promo.get('by_customer') or {}).items()}; bg=promo.get('by_group') or {}; bgp=promo.get('by_group_plan') or {}; glob=float(promo.get('global') or 0)
rows=[]
mm=nm.query("SELECT MIN(customer_id) mn, MAX(customer_id) mx FROM subscriptions WHERE status='subscribed'")['rows'][0]
for lo in range(int(mm['mn'] or 0), int(mm['mx'] or 0)+1, 2500):
    rows += nm.query(f"""
    SELECT s.customer_id,c.group_id,s.plan,ROUND(s.listed_price,2) listed,s.billing_day_mod30
    FROM subscriptions s JOIN customers c USING(customer_id)
    WHERE s.status='subscribed' AND c.customer_type='small' AND s.customer_id BETWEEN {lo} AND {lo+2499}
    """)['rows']
init_counts=defaultdict(float)
for r in rows:
    g,p,cid=r['group_id'],r['plan'],str(r['customer_id'])
    listed=float(r['listed'])
    pr=glob+float(bg.get(g,0) or 0)+float((bgp.get(g,{}) or {}).get(p,0) or 0)+float(bc.get(cid,0) or 0)
    price=round(max(0.0, listed-pr),2)
    init_counts[(g,p,price,int(r['billing_day_mod30']))]+=1
usage_base={('S1','A'):78.0,('S1','B'):58.1,('S1','C'):147.0,('S2','A'):127.7,('S3','A'):327.2,('S3','B'):396.5,('S3','C'):412.9}
public_price={'A':12.99,'B':49.0,'C':99.0}
first_price={('S1','A'):4.99,('S2','A'):12.99,('S3','A'):0.0,('S3','B'):29.0,('S3','C'):79.0}

def target_price(g,p):
    if g=='S1' and p=='A': return 12.99
    if g=='S3' and p=='B': return 49.0
    if g=='S3' and p=='C': return 99.0
    if g=='S3' and p=='A': return 12.99
    return public_price[p]

def churn_for(params,g,p,price,week,c_tier2=False):
    if g=='S1' and p=='A':
        if price<=10.5: base=params.get('s1a_10',0.62)
        elif price<=13.5: base=params.get('s1a_13',0.72)
        elif price<=16.5: base=params.get('s1a_16',0.84)
        else: base=params.get('s1a_high',0.94)
    elif g=='S2': base=params.get('s2_churn',0.96)
    elif g=='S3' and p=='A': base=params.get('s3a',0.99)
    elif g=='S3' and p=='B':
        if price<=40.5: base=params.get('s3b_39',0.60)
        elif price<=50.5: base=params.get('s3b_49',0.71)
        elif price<=60.5: base=params.get('s3b_59',0.80)
        else: base=params.get('s3b_high',0.90)
    elif g=='S3' and p=='C':
        if c_tier2: base=params.get('s3c_99_tier2_churn',0.55)
        elif price<=80.5: base=params.get('s3c_low',0.10)
        elif price<=100.5: base=params.get('s3c_99',0.21)
        elif price<=120.5: base=params.get('s3c_119',0.55)
        else: base=params.get('s3c_high',0.85)
    else: base=params.get('other_churn',0.55)
    decay=1.0 - params.get('shock_decay',0.02)*(1-math.exp(-week/6.0))
    drift=1.0 + params.get('churn_drift_per_week',0.012)*week
    base=max(0.005,base*decay*drift)
    sd=max(0.005,abs(base)*params.get('churn_cv',0.24))
    return max(0,min(params.get('max_churn',0.995),random.gauss(base,sd)))

def spend_for(params,t,cash):
    # Current action: global ops 500 + S3 targeted 500 = 1000/day, dev 0.
    if cash < params.get('desperation_cash',55000): return params.get('ops_desperation',150),0
    if cash < params.get('crisis_cash',80000): return params.get('ops_crisis',500),0
    if cash < params.get('caution_cash',105000): return params.get('ops_caution',700),0
    return params.get('ops',1000),0

def maybe_c_tier2(params,t,cash):
    after=params.get('c_tier2_after_days',9999)
    return t>=after or (t>=params.get('c_tier2_cash_after_days',28) and cash<params.get('c_tier2_cash',85000))

def capacity_cost(params,modeled_units,t):
    peak=modeled_units*params.get('peak_factor',1.35)
    if t>=params.get('tier2_after_days',21) and peak<params.get('tier2_safe_peak',760000): return 530
    return 1330

def simulate(params,seed=0,days=182):
    random.seed(seed); state=defaultdict(float, init_counts); cash=cash0; weekly=[]; c_tier2=False
    for t in range(1,days+1):
        day=DAY+t; week=t/7.0; c_tier2=c_tier2 or maybe_c_tier2(params,t,cash)
        new_state=defaultdict(float)
        for (g,p,price,bm),n in list(state.items()):
            if n<=0: continue
            if bm==day%30:
                ch=churn_for(params,g,p,price,week,c_tier2=(c_tier2 and p=='C'))
                remain=n*(1-ch)
                moves=[(p,price,remain)]
                def gr(name,default,cap):
                    val=random.gauss(params.get(name,default), max(.001,params.get(name,default)*params.get('move_cv',.35)))
                    return max(0,min(cap,val))
                if g=='S3' and p=='C':
                    if c_tier2:
                        toB=gr('s3c_tier2_to_b',0.35,0.85); toA=gr('s3c_tier2_to_a',0.04,0.15)
                    else:
                        toB=gr('s3c_to_b',0.025,0.15); toA=gr('s3c_to_a',0.004,0.04)
                    sc=min(1,0.85/max(1e-9,toB+toA)); nb=remain*toB*sc; na=remain*toA*sc
                    moves=[('C',target_price(g,'C'),remain-nb-na),('B',target_price(g,'B'),nb),('A',target_price(g,'A'),na)]
                elif g=='S3' and p=='B':
                    toA=gr('s3b_to_a',0.05,0.22); toC=gr('s3b_to_c',0.006,0.05); sc=min(1,0.25/max(1e-9,toA+toC))
                    na=remain*toA*sc; nc=remain*toC*sc; moves=[('B',target_price(g,'B'),remain-na-nc),('A',target_price(g,'A'),na),('C',target_price(g,'C'),nc)]
                elif g=='S3' and p=='A':
                    toB=gr('s3a_to_b',0.02,0.10); toC=gr('s3a_to_c',0.002,0.03); nb=remain*toB; nc=remain*toC
                    moves=[('A',target_price(g,'A'),remain-nb-nc),('B',target_price(g,'B'),nb),('C',target_price(g,'C'),nc)]
                for p2,price2,cnt in moves:
                    if cnt>0:
                        cash += cnt*price2; new_state[(g,p2,round(price2,2),bm)] += cnt
            else:
                new_state[(g,p,price,bm)] += n
        state=new_state
        lead_scale=max(0.10,params.get('lead_scale',1.0)*math.exp(params.get('lead_trend',-0.035)*week))
        leads_s1=max(0,random.gauss(params.get('leads_s1',115)*lead_scale, params.get('lead_noise',1.0)*35))
        leads_s2=max(0,random.gauss(params.get('leads_s2',5)*lead_scale, params.get('lead_noise',1.0)*4))
        leads_s3=max(0,random.gauss(params.get('leads_s3',30)*lead_scale, params.get('lead_noise',1.0)*14))
        cs1=max(0,min(0.025,random.gauss(params.get('conv_s1',0.0015), params.get('conv_noise',1.0)*0.0025)))
        cs2=max(0,min(0.008,random.gauss(params.get('conv_s2',0.0), params.get('conv_noise',1.0)*0.001)))
        cs3=max(0,min(0.02,random.gauss(params.get('conv_s3',0.0008), params.get('conv_noise',1.0)*0.002)))
        adds=[('S1','A',leads_s1*cs1),('S2','A',leads_s2*cs2),('S3','C',leads_s3*cs3*.70),('S3','B',leads_s3*cs3*.25),('S3','A',leads_s3*cs3*.05)]
        bm=day%30
        for g,p,cnt in adds:
            if cnt>0:
                cash += cnt*first_price.get((g,p),target_price(g,p)); state[(g,p,round(target_price(g,p),2),bm)] += cnt
        cash -= 0.5*(leads_s1+leads_s2+leads_s3)
        cost_per={'A':0.0003,'B':0.002,'C':(0.002 if c_tier2 else 0.006)}
        modeled_units=0.0; comp=0.0
        for (g,p,price,bm),n in state.items():
            u=usage_base.get((g,p),150)*params.get('usage_mult',1.0); modeled_units += n*u; comp += n*u*cost_per[p]
        comp=max(0,comp*random.gauss(1.0,params.get('compute_cv',0.10)))
        cash -= (capacity_cost(params,modeled_units,t)+spend_for(params,t,cash)[0]+comp)
        if t%7==0: weekly.append(cash)
    return weekly

