import novamind_api as nm, json, re
DAY=nm.vars.current_day
q=lambda sql:nm.query(sql).get('rows',[])
# parse current/last promo config (day252 before week) to infer intended target prices for subscriptions that cancelled or paid
promorow=q("SELECT settings_json FROM config_overrides WHERE setting_type='promotion' ORDER BY id DESC LIMIT 1")
promo=json.loads(promorow[0]['settings_json']) if promorow else {'global':0,'by_group':{},'by_customer':{}}
bycust={int(k):float(v) for k,v in promo.get('by_customer',{}).items()}
bygroup={k:float(v) for k,v in promo.get('by_group',{}).items()}
glob=float(promo.get('global',0) or 0)
# paid cids/amounts last 7
paid=[]
for row in q(f"SELECT day, amount, note FROM ledger WHERE category='subscription_payment' AND day>{DAY-7}"):
    m=re.search(r'customer (\d+)', row.get('note') or '')
    if m: paid.append({'customer_id':int(m.group(1)),'amount':float(row['amount']),'day':row['day']})
# fetch details for paid cids one by one/group chunks
ids=[p['customer_id'] for p in paid]
details={}
for i in range(0,len(ids),500):
    chunk=ids[i:i+500]
    if not chunk: continue
    rows=q(f"""
    SELECT s.customer_id,c.group_id,s.plan,s.listed_price,s.effective_price,s.status,s.start_day,s.end_day,s.seat_count
    FROM subscriptions s JOIN customers c USING(customer_id)
    WHERE s.customer_id IN ({','.join(map(str,chunk))})
    ORDER BY s.customer_id, CASE WHEN s.status='subscribed' THEN 0 ELSE 1 END, s.start_day DESC
    """)
    for r in rows:
        details.setdefault(int(r['customer_id']),r)
# cancellations last7
canc=q(f"""
SELECT s.customer_id,c.group_id,s.plan,s.listed_price,s.effective_price,s.status,s.start_day,s.end_day,s.seat_count
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE s.status='cancelled' AND s.end_day>{DAY-7}
ORDER BY s.customer_id
""")
# target function at old config
def target_for(r):
    cid=int(r['customer_id']); lp=float(r['listed_price']); g=r['group_id']
    promo_amt=glob+bygroup.get(g,0)+bycust.get(cid,0)
    return round(max(0,lp-promo_amt),2)
agg={}
def add(kind,r,amount=0):
    k=(r['group_id'],r['plan'],target_for(r))
    a=agg.setdefault(k,{'group_id':k[0],'plan':k[1],'target':k[2],'paid_n':0,'paid_amt':0,'cancel_n':0,'cancel_eff_prices':{}})
    if kind=='paid':
        a['paid_n']+=1; a['paid_amt']+=amount
    else:
        a['cancel_n']+=1; ep=round(float(r['effective_price']),2); a['cancel_eff_prices'][str(ep)]=a['cancel_eff_prices'].get(str(ep),0)+1
for p in paid:
    r=details.get(p['customer_id'])
    if r: add('paid',r,p['amount'])
for r in canc:
    add('cancel',r,0)
out=[]
for a in agg.values():
    denom=a['paid_n']+a['cancel_n']
    a['retention_pct']=round(100*a['paid_n']/denom,1) if denom else None
    out.append(a)
print(json.dumps(sorted(out,key=lambda x:(x['group_id'],x['plan'],x['target'])),indent=2))

