def target_price(g,p): return public_price[p]

def churn_for(params,g,p,price,week,c_tier2=False):
    # monthly churn at billing under emergency lower prices; wide uncertainty.
    if g=='S1' and p=='A': base=params.get('s1a_low',0.62)
    elif g=='S2': base=params.get('s2_churn',0.95)
    elif g=='S3' and p=='A': base=params.get('s3a_low',0.82)
    elif g=='S3' and p=='B': base=params.get('s3b_29',0.55)
    elif g=='S3' and p=='C':
        base=params.get('s3c_tier2_churn',0.78) if c_tier2 else params.get('s3c_79',0.14)
    else: base=params.get('other_churn',0.60)
    # competitive drift/support fatigue gradually worsens retention until drastic harvest cuts.
    drift=1.0 + params.get('churn_drift_per_week',0.018)*week
