def maybe_c_tier2(params,t,cash):
    # Harvest tactic: keep C tier3 through current billing window, then switch if cash pressure is high.
    if t >= params.get('force_c_tier2_after',9999): return True
    if t >= params.get('c_tier2_after_days',28) and cash < params.get('c_tier2_cash',70000): return True
    if t >= params.get('c_tier2_emergency_after',21) and cash < params.get('c_tier2_emergency_cash',45000): return True
    return False

def capacity_cost(params,modeled_units):
    peak=modeled_units*params.get('peak_factor',1.20)
    if peak < 45000: return 85
    if peak < 185000: return 215
    if peak < params.get('tier2_limit',790000): return 530
    return 1330

def simulate(params,seed=0,days=182):
    random.seed(seed); state=defaultdict(float, init_counts); cash=cash0; weekly=[]; c_tier2=False
