    if g=='S3' and p=='A': return sample_rate(params,'s3a_499',.80,week)
    if g=='S3' and p=='B': return sample_rate(params,'s3b_19',.35,week)
    if g=='S3' and p=='C': return sample_rate(params,'s3c_69_quota150',.45,week)
    if p=='C': return sample_rate(params,'other_c',.50,week)
    return sample_rate(params,'other',.60,week)

def capacity_cost(modeled_units):
    # weekly controller: tier0 if very small, else tier1 (new caps should keep peak <200k for current book)
    peak=modeled_units*1.18
    if peak < 47000: return 85
    if peak < 190000: return 215
    return 530

def ops_cost(params,cash,t):
    # Current global+targeted ops = 600/day. Future weeks cut if cash deteriorates.
    if cash < params.get('ops_panic_cash',25000): return params.get('ops_panic',75)
    if cash < params.get('ops_crisis_cash',40000): return params.get('ops_crisis',250)
    if cash < params.get('ops_caution_cash',55000): return params.get('ops_caution',500)
    return params.get('ops_current',600)

def simulate(params, seed=0, days=182):
    random.seed(seed); state=defaultdict(float, init_counts); cash=cash0; weekly=[]
    for t in range(1,days+1):
        day=DAY+t; week=t/7.0; new_state=defaultdict(float)
        for (g,p,price,bm),n in list(state.items()):
            if n<=0: continue
            if bm==day%30:
                ch=churn_for(params,g,p,price,week)
                remain=n*(1-ch)
                # Plan-change behavior. Retained C users sometimes downgrade to B under stability quotas; B users can upgrade if they need C quality.
                moves=[]
                def gr(mu,cv=.45,cap=.8): return max(0,min(cap,random.gauss(mu, max(.001,mu*cv))))
                if g=='S3' and p=='C':
                    toB=gr(params.get('s3c_to_b',.08),cap=.35); toA=gr(params.get('s3c_to_a',.01),cap=.08)
                    sc=min(1,.45/max(1e-9,toB+toA)); nb=remain*toB*sc; na=remain*toA*sc
                    moves=[('C',remain-nb-na),('B',nb),('A',na)]
                elif g=='S3' and p=='B':
                    toC=gr(params.get('s3b_to_c',.04),cap=.20); toA=gr(params.get('s3b_to_a',.04),cap=.20)
                    nc=remain*toC; na=remain*toA; moves=[('B',remain-nc-na),('C',nc),('A',na)]
                elif g=='S1' and p=='B':
                    toA=gr(params.get('s1b_to_a',.08),cap=.30); moves=[('B',remain*(1-toA)),('A',remain*toA)]
                else:
                    moves=[(p,remain)]
                for p2,cnt in moves:
                    if cnt>0:
                        price2=round(target_price(g,p2),2); cash += cnt*price2; new_state[(g,p2,price2,bm)] += cnt
            else:
                new_state[(g,p,price,bm)] += n
        state=new_state
        active=sum(state.values())
        # organic leads only; no ads/in-app ads. Scale down with reputation/active book.
        lead_scale=max(.05,(active/2103.0)**params.get('lead_elasticity',.75)*math.exp(params.get('lead_trend',-.035)*week))
        leads_s1=max(0,random.gauss(params.get('leads_s1',45)*lead_scale, params.get('lead_sd',10)))
        leads_s3=max(0,random.gauss(params.get('leads_s3',18)*lead_scale, params.get('lead_sd_s3',5)))
        leads_s2=max(0,random.gauss(params.get('leads_s2',3)*lead_scale, 1.5))
        conv_s1=max(0,min(.08,random.gauss(params.get('conv_s1',.006), params.get('conv_sd',.006))))
        conv_s3=max(0,min(.05,random.gauss(params.get('conv_s3',.003), params.get('conv_sd_s3',.004))))
        conv_s2=max(0,min(.03,random.gauss(params.get('conv_s2',.001), .002)))
        adds=[('S1','A',leads_s1*conv_s1),('S2','A',leads_s2*conv_s2),('S3','C',leads_s3*conv_s3*.60),('S3','B',leads_s3*conv_s3*.35),('S3','A',leads_s3*conv_s3*.05)]
        bm=day%30
        for g,p,cnt in adds:
            if cnt>0:
                price=round(target_price(g,p),2); cash += cnt*price; state[(g,p,price,bm)] += cnt
        cash -= 0.5*(leads_s1+leads_s2+leads_s3)
        modeled_units=0.0; comp=0.0
        for (g,p,price,bm),n in state.items():
            u=usage_base.get((g,p),50.0)*params.get('usage_mult',1.0)
            modeled_units += n*u; comp += n*u*({'A':.0003,'B':.002,'C':.006}[p])
        comp=max(0,comp*random.gauss(1.0,params.get('compute_cv',.08)))
        cash -= comp + capacity_cost(modeled_units) + ops_cost(params,cash,t)
        if t%7==0: weekly.append(cash)
    return weekly

