import novamind_api as nm, json, re, collections
DAY=nm.vars.current_day
q=lambda sql:nm.query(sql).get('rows',[])
promorow=q("SELECT settings_json FROM config_overrides WHERE setting_type='promotion' ORDER BY id DESC LIMIT 1")
promo=json.loads(promorow[0]['settings_json']) if promorow else {'global':0,'by_group':{},'by_customer':{},'by_group_plan':{}}
bycust={int(k):float(v) for k,v in promo.get('by_customer',{}).items()}
bygroup={k:float(v) for k,v in (promo.get('by_group') or {}).items()}
bygplan=promo.get('by_group_plan') or {}
glob=float(promo.get('global',0) or 0)
def pfor(cid,g,plan): return glob+bygroup.get(g,0)+float((bygplan.get(g) or {}).get(plan,0) or 0)+bycust.get(cid,0)
def target_for(r): return round(max(0,float(r['listed_price'])-pfor(int(r['customer_id']),r['group_id'],r['plan'])),2)
paid=[]
for row in q(f"SELECT day, amount, note FROM ledger WHERE category='subscription_payment' AND day>{DAY-7}"):
    m=re.search(r'customer (\d+)', row.get('note') or '')
    if m: paid.append({'customer_id':int(m.group(1)),'amount':float(row['amount']),'day':row['day']})
ids=[p['customer_id'] for p in paid]
details={}
for i in range(0,len(ids),500):
    chunk=ids[i:i+500]
    if not chunk: continue
    rows=q(f"""
    SELECT s.customer_id AS customer_id,c.group_id AS group_id,s.plan AS plan,s.listed_price AS listed_price,s.effective_price AS effective_price,s.status AS status,s.start_day AS start_day,s.end_day AS end_day
    FROM subscriptions s JOIN customers c USING(customer_id)
    WHERE s.customer_id IN ({','.join(map(str,chunk))})
    ORDER BY s.customer_id, CASE WHEN s.status='subscribed' THEN 0 ELSE 1 END, s.start_day DESC
    """)
    for r in rows: details.setdefault(int(r['customer_id']),r)
canc=q(f"""
SELECT s.customer_id AS customer_id,c.group_id AS group_id,s.plan AS plan,s.listed_price AS listed_price,s.effective_price AS effective_price,s.status AS status,s.start_day AS start_day,s.end_day AS end_day,s.billing_day_mod30 AS billing_day_mod30
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE s.status='cancelled' AND s.end_day>{DAY-7}
ORDER BY s.customer_id
""")
agg={}
def add(kind,r,amount=0,day=None):
    k=(r['group_id'],r['plan'],target_for(r))
    a=agg.setdefault(k,{'group_id':k[0],'plan':k[1],'target':k[2],'paid_n':0,'paid_amt':0,'cancel_n':0,'cancel_eff_prices':{},'cancel_days':{}})
    if kind=='paid':
        a['paid_n']+=1; a['paid_amt']+=amount
    else:
        a['cancel_n']+=1; ep=round(float(r['effective_price']),2); a['cancel_eff_prices'][str(ep)]=a['cancel_eff_prices'].get(str(ep),0)+1; d=int(r.get('end_day') or day or -1); a['cancel_days'][str(d)]=a['cancel_days'].get(str(d),0)+1
for p in paid:
    r=details.get(p['customer_id'])
    if r: add('paid',r,p['amount'],p['day'])
for r in canc: add('cancel',r,0,r.get('end_day'))
out=[]
for a in agg.values():
    denom=a['paid_n']+a['cancel_n']; a['retention_pct']=round(100*a['paid_n']/denom,1) if denom else None; out.append(a)
print(json.dumps(sorted(out,key=lambda x:(x['group_id'],x['plan'],x['target'])),indent=2))

