arguments.content:
import novamind_api as nm, json
DAY=nm.vars.current_day
q=lambda sql:nm.query(sql).get('rows',[])
print('DAY',DAY)
print('config', json.dumps(q('SELECT * FROM config_history ORDER BY day DESC LIMIT 1'),indent=2))
# latest override compact
for r in q("SELECT setting_type, day, settings_json FROM config_overrides co JOIN (SELECT setting_type st, MAX(id) mid FROM config_overrides GROUP BY setting_type) m ON co.setting_type=m.st AND co.id=m.mid ORDER BY setting_type"):
    js=json.loads(r['settings_json']);
    if r['setting_type']=='promotion': js={'global':js.get('global'), 'by_group':js.get('by_group'), 'by_group_plan':js.get('by_group_plan'), 'by_customer_count':len(js.get('by_customer',{}))}
    print(r['setting_type'], r['day'], js)
# target price parse
promo=json.loads(q("SELECT settings_json FROM config_overrides WHERE setting_type='promotion' ORDER BY id DESC LIMIT 1")[0]['settings_json'])
bycust={int(k):float(v) for k,v in promo.get('by_customer',{}).items()}; glob=float(promo.get('global') or 0); bygroup=promo.get('by_group') or {}; bygplan=promo.get('by_group_plan') or {}
def pfor(cid,g,plan): return glob+float(bygroup.get(g,0) or 0)+float((bygplan.get(g) or {}).get(plan,0) or 0)+bycust.get(cid,0)
active=q("SELECT s.customer_id AS customer_id,c.group_id AS group_id,s.plan AS plan,s.listed_price AS listed_price,s.billing_day_mod30 AS billing_day_mod30 FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed'")
agg={}
for r in active:
    cid=int(r['customer_id']); g=r['group_id']; p=r['plan']; target=round(max(0,float(r['listed_price'])-pfor(cid,g,p)),2); delta=(int(r['billing_day_mod30'])-(DAY%30)+30)%30
    win='d0_7' if delta<=7 else 'd8_14' if delta<=14 else 'd15_21' if delta<=21 else 'd22_29'
    k=(win,g,p,target); a=agg.setdefault(k,{'win':win,'group_id':g,'plan':p,'target':target,'subs':0,'bill':0.0}); a['subs']+=1; a['bill']+=target
print('target_total_mrr', round(sum(v['bill'] for v in agg.values()),2))
print(json.dumps(sorted([{**v,'bill':round(v['bill'],2)} for v in agg.values()], key=lambda x:(x['win'],x['group_id'],x['plan'],x['target'])),indent=2))
print('cost_info', json.dumps(nm.infrastructure.get_cost_info(),indent=2))

