./novamind-operation python-c "import novamind_api as nm, re
rows=nm.query(\"SELECT day,amount,note FROM ledger WHERE category='subscription_payment' AND day>=250 ORDER BY day DESC LIMIT 2000\")['rows']
ids=[]
for row in rows:
    m=re.search(r'customer (\d+)', row['note']);
    if m: ids.append(int(m.group(1)))
ids=ids[:200]
if ids:
    idlist=','.join(map(str,ids))
    subs=nm.query(f\"SELECT customer_id,start_day,end_day,status,plan,listed_price,effective_price,billing_day_mod30 FROM subscriptions WHERE customer_id IN ({idlist})\")['rows']
    sd={s['customer_id']:s for s in subs}
    for row in rows[:50]:
      m=re.search(r'customer (\d+)', row['note']); cid=int(m.group(1)); s=sd.get(cid,{}); print(row, 'start', s.get('start_day'), 'delta', row['day']-s.get('start_day',0), 'status', s.get('status'))
"

