./novamind-operation python-c "import novamind_api as nm; 
# average ad revenue by group/customer over historical ads strength 1/0.5
q='''SELECT group_id, ROUND(AVG(revenue),4) avg_rev, COUNT(*) n, MIN(revenue) minrev, MAX(revenue) maxrev, ROUND(AVG(ads_strength),3) avg_strength FROM ads_revenue GROUP BY group_id'''
try:
 for row in nm.query(q)['rows']: print(row)
except Exception as e: print(e)
"

