import novamind_api as nm
import json, textwrap

def q(sql):
    try:
        return nm.query(sql)['rows']
    except Exception as e:
        return [{'ERROR':str(e)}]

print('day', nm.vars.current_day)
print('market overview')
try:
    print(json.dumps(nm.market.get_market_overview(), indent=2)[:4000])
except Exception as e: print('market err', e)
print('cost info')
try:
    print(json.dumps(nm.infrastructure.get_cost_info(), indent=2)[:4000])
except Exception as e: print('cost err', e)

queries={
'cash': "SELECT SUM(amount) cash FROM ledger",
'ledger_7d': "SELECT category, COUNT(*) n, ROUND(SUM(amount),2) amt FROM ledger WHERE day>=(SELECT MAX(day) FROM ledger)-6 GROUP BY category ORDER BY amt",
'ledger_30d': "SELECT category, COUNT(*) n, ROUND(SUM(amount),2) amt FROM ledger WHERE day>=(SELECT MAX(day) FROM ledger)-29 GROUP BY category ORDER BY amt",
'ledger_all': "SELECT category, COUNT(*) n, ROUND(SUM(amount),2) amt FROM ledger GROUP BY category ORDER BY amt",
'sub_status': "SELECT status, COUNT(*) n, COALESCE(SUM(seat_count),0) seats FROM subscriptions GROUP BY status",
'active_by_group': "SELECT c.group_id, s.plan, COUNT(*) n, SUM(s.seat_count) seats, AVG(s.effective_price) avg_price FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan",
'customers_by_group_status': "SELECT c.group_id, c.acquisition_source, s.status, COUNT(*) n, COALESCE(SUM(s.seat_count),0) seats FROM subscriptions s JOIN customers c USING(customer_id) GROUP BY c.group_id,c.acquisition_source,s.status ORDER BY c.group_id,s.status,n DESC LIMIT 100",
'recent_customers': "SELECT c.customer_id,c.created_day,c.customer_type,c.group_id,c.acquisition_source,s.status,s.plan,s.listed_price,s.effective_price,s.seat_count,s.start_day,s.end_day FROM customers c LEFT JOIN subscriptions s USING(customer_id) WHERE c.created_day>=300 ORDER BY c.created_day DESC, c.customer_id DESC LIMIT 100",
'open_enterprise': "SELECT message_id,customer_id,thread_type,turn_number,sender,day,seat_count,closed,close_reason,message_text,offer_json FROM enterprise_turns WHERE closed=0 ORDER BY day,message_id LIMIT 100",
'recent_enterprise': "SELECT message_id,customer_id,thread_type,turn_number,sender,day,seat_count,closed,close_reason,substr(message_text,1,180) msg,offer_json FROM enterprise_turns WHERE day>=300 ORDER BY day DESC,message_id DESC LIMIT 100",
'agent_posts': "SELECT * FROM agent_social_media_posts ORDER BY day DESC LIMIT 20",
'social_recent': "SELECT post_id,day,author_type,customer_id,group_id,substr(content,1,220) content,reply_to_post_id,views,likes,comments FROM social_media_posts WHERE day>=320 ORDER BY day DESC,post_id DESC LIMIT 80",
'service_recent': "SELECT * FROM service_day ORDER BY day DESC LIMIT 10",
'issues': "SELECT status, COUNT(*) n FROM issues GROUP BY status",
'open_issues': "SELECT * FROM issues WHERE status!='resolved' ORDER BY created_day DESC LIMIT 20",
}
for name,sql in queries.items():
    print('\n--', name, '--')
    rows=q(sql)
    for r in rows[:200]: print(r)

# insights for initial groups
for gid in ['S1','S2','S3','E1','E2','E3']:
    try:
        ins=nm.market.get_group_insights(gid)
        print('\nINSIGHT', gid)
        print(json.dumps(ins, indent=2)[:3000])
    except Exception as e: print('ins err',gid,e)

try:
    posts=nm.analytics.get_social_posts(days=21, limit=100)
    print('\nAPI social posts keys', posts.keys() if isinstance(posts,dict) else type(posts))
    pp=posts.get('posts', posts) if isinstance(posts,dict) else posts
    print(json.dumps(pp[:20] if isinstance(pp,list) else pp, indent=2)[:5000])
except Exception as e: print('api social err', e)

try:
    print('\nresearch projects')
    print(json.dumps(nm.research.list_research_projects(), indent=2)[:5000])
except Exception as e: print('research err', e)

