import novamind_api as nm, json

def print_rows(name, sql):
    print('\n--'+name+'--')
    try:
        rows=nm.query(sql)['rows']
        for r in rows: print(r)
    except Exception as e: print('ERR',e)

print('day',nm.vars.current_day)
print_rows('agent_posts', "SELECT * FROM agent_social_media_posts ORDER BY day DESC, agent_post_id DESC LIMIT 30")
print_rows('comments_to_agent48', "SELECT post_id,day,author_type,customer_id,group_id,source_group_id,substr(content,1,280) content,reply_to_agent_post_id,views,likes,comments FROM social_media_posts WHERE reply_to_agent_post_id=48 ORDER BY day,post_id")
print_rows('social_329_plus', "SELECT post_id,day,author_type,customer_id,group_id,source_group_id,substr(content,1,260) content,reply_to_agent_post_id,views,likes,comments FROM social_media_posts WHERE day>=329 ORDER BY day DESC,post_id DESC LIMIT 100")
print_rows('agent table schema?', "PRAGMA table_info(agent_social_media_posts)")
print_rows('social table schema?', "PRAGMA table_info(social_media_posts)")
try:
    posts=nm.analytics.get_social_posts(days=14, limit=100)
    print('\nAPI total', posts.get('total'))
    for p in posts.get('posts',[])[:100]: print(p)
except Exception as e: print('api err',e)

