import novamind_api as nm
queries={
'usage_by_group_plan': """
SELECT c.group_id,s.plan,COUNT(DISTINCT du.customer_id) users,COUNT(*) days,ROUND(AVG(du.usage_units),1) avg_u,ROUND(MAX(du.usage_units),1) max_u,ROUND(SUM(du.usage_units),1) total_u
FROM daily_usage du JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id)
GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan
""",
'usage_recent': "SELECT day, COUNT(DISTINCT customer_id) users, SUM(usage_units) units, AVG(usage_units) avg_u, MAX(usage_units) max_u FROM daily_usage WHERE day>=250 GROUP BY day ORDER BY day DESC LIMIT 70",
'lead_counts_by_day_since250': "SELECT c.created_day day,c.group_id,c.acquisition_source,s.status,COUNT(*) n FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day>=250 GROUP BY c.created_day,c.group_id,c.acquisition_source,s.status ORDER BY day DESC,c.group_id,status LIMIT 200",
'payments_since250': "SELECT day,category,COUNT(*) n,ROUND(SUM(amount),2) amt FROM ledger WHERE day>=250 AND category IN ('subscription_payment','compute','capacity','lead_acquisition_cost','advertising','development','operations','ad_revenue') GROUP BY day,category ORDER BY day DESC,category LIMIT 250",
'config_recent': "SELECT * FROM config_history WHERE day>=280 ORDER BY day DESC, id DESC LIMIT 200",
'config_overrides': "SELECT * FROM config_overrides ORDER BY rowid DESC LIMIT 200",
}
for name,sql in queries.items():
 print('\n--',name,'--')
 try:
  rows=nm.query(sql)['rows']
  for r in rows[:300]: print(r)
 except Exception as e: print('ERR',e)

