import novamind_api as nm
queries={
'customers_by_group_source':"SELECT group_id, acquisition_source, COUNT(*) n FROM customers GROUP BY group_id, acquisition_source ORDER BY group_id, n DESC",
'subscriptions_by_status_group':"SELECT c.group_id, s.status, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id GROUP BY c.group_id,s.status ORDER BY c.group_id,s.status",
'active_statuses':"SELECT status, COUNT(*) n FROM subscriptions GROUP BY status",
'payments_by_group':"SELECT c.group_id, COUNT(*) payments, SUM(l.amount) revenue FROM ledger l JOIN customers c ON instr(l.note, CAST(c.customer_id AS TEXT))>0 WHERE l.category='subscription_payment' GROUP BY c.group_id ORDER BY revenue DESC",
'ledger_revenue':"SELECT category, SUM(amount) amt, COUNT(*) n FROM ledger GROUP BY category ORDER BY amt DESC",
'lead_cost_recent':"SELECT category, SUM(amount) amt, COUNT(*) n FROM ledger WHERE category LIKE '%lead%' GROUP BY category",
}
for name,q in queries.items():
    print('\n--',name)
    try:
