def sim(weeks, cohort_rev, cohort_compute_week, usage_per_cohort, continue_weeks=12, ops_week=700, adlead_week=1100, retention=.85):
 cash=start; cohorts=[]
 for w in range(1,weeks+1):
  if w<=continue_weeks:
   cash-=adlead_week+ops_week; cash+=cohort_rev; cohorts.append({'age':0,'frac':1})
  elif cohorts: cash-=ops_week
  for c in cohorts:
   if c['age']>0 and c['age']%4==0:
    cash+=cohort_rev*c['frac']; c['frac']*=retention
  usage=sum(c['frac'] for c in cohorts)*usage_per_cohort
  cash-= 595 if usage<=50000 else 1505 if usage<=200000 else 3710
  for c in cohorts: cash-=cohort_compute_week*c['frac']*(.5 if c['age']==0 else 1)
  for c in cohorts: c['age']+=1
 return cash
for rev,comp,usage,ret,name in [(4453,644,14100,.85,'conserv'),(6241,902,19800,.9,'base'),(2500,400,9000,.8,'low')]:
 print(name, sim(20,rev,comp,usage,12,retention=ret))
