import novamind_api as nm, json, re, statistics
queries={
'cash_by_week': "SELECT (day/7)*7 as wk, SUM(amount) as net, SUM(CASE WHEN amount>0 THEN amount ELSE 0 END) as rev, SUM(CASE WHEN amount<0 THEN amount ELSE 0 END) as cost FROM ledger GROUP BY (day/7) ORDER BY wk",
'ledger_cats': "SELECT category, SUM(amount) amt, COUNT(*) n FROM ledger GROUP BY category ORDER BY amt DESC",
'configs_recent': "SELECT * FROM config_history ORDER BY day DESC LIMIT 40",
'configs_changed': "SELECT day, price_A,price_B,price_C,tier_A,tier_B,tier_C,quota_A,quota_B,quota_C,spend_advertising,spend_operations,spend_development,capacity_tier FROM config_history WHERE day%7=0 OR day>=280 ORDER BY day",
'sub_starts_by_week_group_status': "SELECT (s.start_day/7)*7 wk, c.group_id, s.status, COUNT(*) n, AVG(s.listed_price) avg_list, AVG(s.effective_price) avg_eff, AVG(CASE WHEN s.plan='A' THEN 1 ELSE 0 END) fracA, AVG(CASE WHEN s.plan='B' THEN 1 ELSE 0 END) fracB, AVG(CASE WHEN s.plan='C' THEN 1 ELSE 0 END) fracC FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id GROUP BY wk,c.group_id,s.status ORDER BY wk,c.group_id,s.status",
'sub_agg_group_plan_status': "SELECT c.group_id, s.plan, s.status, COUNT(*) n, AVG(s.listed_price) avg_list, AVG(s.effective_price) avg_eff, AVG(COALESCE(s.end_day, 322)-s.start_day) avg_days FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id GROUP BY c.group_id,s.plan,s.status ORDER BY c.group_id,s.plan,s.status",
'payments_notes_sample': "SELECT day, amount, note FROM ledger WHERE category='subscription_payment' ORDER BY day DESC LIMIT 20",
'enterprise_payments': "SELECT * FROM ledger WHERE category='subscription_payment' AND note LIKE '%seat%' ORDER BY day DESC LIMIT 20"
}
for name,q in queries.items():
    print('\n##',name)
    try:
        r=nm.query(q)
        rows=r['rows']
        print('rows',len(rows),'warn',r.get('warning'))
        print(json.dumps(rows[:200], indent=2)[:30000])
        if len(rows)>200: print('...')
    except Exception as e: print('ERR',e)

