cat > week54_analyze.py <<'PY'
import novamind_api as nm, json

def q(name, sql):
    print('\n##', name)
    try:
        r=nm.query(sql); rows=r['rows']; print('rows',len(rows),'warn',r.get('warning')); 
        for row in rows[:200]: print(row)
        if len(rows)>200: print('...')
    except Exception as e: print('ERR',e)

print('day', nm.vars.current_day)
q('cash', 'SELECT SUM(amount) cash FROM ledger')
q('ledger day>=372 by category', "SELECT category, COUNT(*) n, ROUND(SUM(amount),4) amount FROM ledger WHERE day>=372 GROUP BY category ORDER BY amount")
q('ledger recent days', "SELECT day, category, ROUND(SUM(amount),4) amount, COUNT(*) n FROM ledger WHERE day>=372 GROUP BY day,category ORDER BY day,category")
q('subs active', "SELECT c.group_id,s.plan,COUNT(*) n,SUM(s.seat_count) seats,ROUND(SUM(s.effective_price*s.seat_count),2) mrr FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id,s.plan")
q('subs starts >=280 by week/group/status', "SELECT (s.start_day/7)*7 wk,c.group_id,c.acquisition_source,s.status,s.plan,COUNT(*) n,ROUND(AVG(s.listed_price),2) avg_list,ROUND(AVG(s.effective_price),2) avg_eff FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.start_day>=280 GROUP BY wk,c.group_id,c.acquisition_source,s.status,s.plan ORDER BY wk,c.group_id,c.acquisition_source,s.status,s.plan")
q('customers created >=280 by week/group/source', "SELECT (created_day/7)*7 wk, group_id, acquisition_source, COUNT(*) n FROM customers WHERE created_day>=280 GROUP BY wk,group_id,acquisition_source ORDER BY wk,group_id,acquisition_source")
q('ad channel leads >=280', "SELECT (day/7)*7 wk, channel_id, group_id, SUM(leads_generated) leads, SUM(spend) spend, ROUND(1.0*SUM(leads_generated)/NULLIF(SUM(spend),0),3) lpd FROM ad_channel_leads WHERE day>=280 GROUP BY wk,channel_id,group_id ORDER BY wk,group_id,channel_id")
q('config recent 20', "SELECT * FROM config_history ORDER BY day DESC LIMIT 30")
q('enterprise open', "SELECT * FROM enterprise_turns WHERE closed=0 ORDER BY day ASC LIMIT 100")
q('issues open/recent', "SELECT * FROM issues WHERE status='open' OR open_day>=350 OR resolved_day>=350 ORDER BY open_day DESC LIMIT 50")
q('service recent', "SELECT * FROM service_day WHERE day>=372 ORDER BY day")
q('agent posts recent', "SELECT * FROM agent_social_posts ORDER BY day DESC LIMIT 10")
# API extra
print('\n## cost_info')
try: print(json.dumps(nm.infrastructure.get_cost_info(), indent=2))
except Exception as e: print('ERR',e)
print('\n## market_overview')
try: print(json.dumps(nm.market.get_market_overview(), indent=2)[:10000])
except Exception as e: print('ERR',e)
print('\n## projects')
try: print(json.dumps(nm.research.list_research_projects(), indent=2)[:10000])
except Exception as e: print('ERR',e)
print('\n## social')
try:
    posts=nm.analytics.get_social_posts(days=30, limit=30)
    print(json.dumps(posts, indent=2)[:20000])
except Exception as e: print('ERR',e)
PY
./novamind-operation python week54_analyze.py > week54_analyze.out
sed -n '1,260p' week54_analyze.out

