import novamind_api as nm
from pprint import pprint
print('day', nm.vars.current_day)
print('cash', nm.query('SELECT SUM(amount) AS cash FROM ledger')['rows'][0]['cash'])
queries = {
 'active_subs_by_group': "SELECT c.group_id, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id,s.plan",
 'subs_status_recent': "SELECT s.status, c.group_id, c.acquisition_source, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.created_day>=413 GROUP BY s.status,c.group_id,c.acquisition_source ORDER BY n DESC",
 'ledger_7d': "SELECT category, COUNT(*) entries, SUM(amount) amount FROM ledger WHERE day>413 GROUP BY category ORDER BY amount",
 'open_enterprise': "SELECT COUNT(*) n FROM enterprise_turns WHERE closed=0",
 'issues': "SELECT status, COUNT(*) n FROM issues GROUP BY status",
 'service': "SELECT day, total_usage_units, p95_ms, error_rate, downtime_minutes, capacity_tier, capacity_units FROM service_day WHERE day>413 ORDER BY day",
}
for name,q in queries.items():
    print('\n--', name)
    try:
        pprint(nm.query(q)['rows'])
    except Exception as e:
        print('ERR', e)
print('\nrecent social')
try:
    posts = nm.analytics.get_social_posts(days=7, limit=10)['posts']
    for p in posts:
        print(p)
except Exception as e:
    print('ERR social', e)

