arguments.content:
import novamind_api as nm
from pprint import pprint
print('day', nm.vars.current_day)
# exact cash
r=nm.query("SELECT SUM(amount) AS cash FROM ledger")
print('cash', r['rows'])
# recent ledger by category last 7 days (days > current_day-7? include current week ledger maybe day428-434)
day=nm.vars.current_day
queries={
 'ledger_by_cat_last7': f"SELECT category, COUNT(*) AS n, SUM(amount) AS amt FROM ledger WHERE day>{day-7} AND day<={day} GROUP BY category ORDER BY amt",
 'ledger_by_day_last10': f"SELECT day, category, SUM(amount) AS amt FROM ledger WHERE day>{day-10} GROUP BY day, category ORDER BY day, category",
 'active_subs': "SELECT c.group_id, s.plan, COUNT(*) AS n, SUM(COALESCE(s.seats,1)) AS seats FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id, s.plan",
 'all_sub_status_recent': f"SELECT s.status, c.group_id, c.acquisition_source, COUNT(*) AS n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.created_day>{day-7} GROUP BY s.status,c.group_id,c.acquisition_source ORDER BY n DESC",
 'enterprise_open': "SELECT COUNT(*) AS n FROM enterprise_turns WHERE closed=0",
 'enterprise_pending_sample': "SELECT * FROM enterprise_turns WHERE closed=0 ORDER BY day ASC LIMIT 20",
 'issues_open': "SELECT COUNT(*) AS n FROM issues WHERE status!='resolved'",
 'service_last7': f"SELECT day,total_usage_units,p95_ms,error_rate,downtime_minutes,capacity_tier,capacity_units FROM service_day WHERE day>{day-7} ORDER BY day",
}
for name,q in queries.items():
    print('\n--', name, '--')
    try:
        res=nm.query(q)
        pprint(res.get('rows'))
        if res.get('warning'): print('warning',res['warning'])
    except Exception as e:
        print('ERR', e)
print('\nMarket overview:')
try: pprint(nm.market.get_market_overview())
except Exception as e: print('market err', e)
print('\nCost info:')
try: pprint(nm.infrastructure.get_cost_info())
except Exception as e: print('cost err', e)
print('\nResearch projects:')
try: pprint(nm.research.list_research_projects())
except Exception as e: print('research err', e)
print('\nRecent social:')
try: pprint(nm.analytics.get_social_posts(days=7, limit=20))
except Exception as e: print('social err', e)

