arguments.content:
import novamind_api as nm
from pprint import pprint

day=nm.vars.current_day
print('day', day)
for name,q in {
    'cash': "SELECT SUM(amount) AS cash FROM ledger",
    'ledger_by_cat_last7': f"SELECT category, COUNT(*) AS n, SUM(amount) AS amt FROM ledger WHERE day>{day-7} AND day<={day} GROUP BY category ORDER BY amt",
    'ledger_by_day_last10': f"SELECT day, category, SUM(amount) AS amt FROM ledger WHERE day>{day-10} GROUP BY day, category ORDER BY day, category",
    'active_subs': "SELECT c.group_id, s.plan, COUNT(*) AS n, SUM(COALESCE(s.seat_count,1)) AS seats FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id, s.plan",
    'new_leads_last7_status': f"SELECT s.status, c.group_id, c.acquisition_source, COUNT(*) AS n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.created_day>{day-7} GROUP BY s.status,c.group_id,c.acquisition_source ORDER BY n DESC",
    'enterprise_open': "SELECT COUNT(*) AS n FROM enterprise_turns WHERE closed=0",
    'enterprise_pending_sample': "SELECT * FROM enterprise_turns WHERE closed=0 ORDER BY day ASC LIMIT 20",
    'issues_open_nonresolved': "SELECT COUNT(*) AS n FROM issues WHERE status!='resolved'",
    'service_last7': f"SELECT day,total_usage_units,p95_ms,error_rate,downtime_minutes,capacity_tier,capacity_units FROM service_day WHERE day>{day-7} ORDER BY day",
}.items():
    print('\n--', name, '--')
    try:
        res=nm.query(q)
        pprint(res.get('rows'))
        if res.get('warning'): print('warning',res['warning'])
    except Exception as e: print('ERR', e)
print('\nCost info:')
try: pprint(nm.infrastructure.get_cost_info())
except Exception as e: print('ERR', e)
print('\nSocial last 7:')
try: pprint(nm.analytics.get_social_posts(days=7, limit=10))
except Exception as e: print('ERR', e)
print('\nResearch:')
try: pprint(nm.research.list_research_projects())
except Exception as e: print('ERR', e)

