import novamind_api as nm, json
print('day', nm.vars.current_day)
for name, sql in {
 'cash': "SELECT SUM(amount) AS cash FROM ledger",
 'ledger_7d': "SELECT category, ROUND(SUM(amount),2) AS amt, COUNT(*) AS n FROM ledger WHERE day > (SELECT MAX(day)-7 FROM ledger) GROUP BY category ORDER BY amt",
 'subs_status': "SELECT status, COUNT(*) AS n FROM subscriptions GROUP BY status",
 'active_by_group': "SELECT c.group_id, s.plan, COUNT(*) n, SUM(COALESCE(c.seat_count,1)) seats FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id,s.plan",
 'open_threads': "SELECT COUNT(*) AS n FROM enterprise_turns WHERE closed=0",
 'service_recent': "SELECT day, capacity_tier, total_usage_units, p95_ms, error_rate, downtime_minutes, capacity_units FROM service_day ORDER BY day DESC LIMIT 10",
 'recent_leads': "SELECT c.group_id, s.status, COUNT(*) n FROM customers c JOIN subscriptions s ON c.customer_id=s.customer_id WHERE c.created_day>=469 GROUP BY c.group_id,s.status ORDER BY n DESC"
}.items():
    try:
        r=nm.query(sql)
        print('\n--', name, '--')
        for row in r['rows'][:20]: print(row)
    except Exception as e:
        print('ERR', name, e)
try:
    ci=nm.infrastructure.get_cost_info(); print('\n-- cost_info --'); print(json.dumps(ci, indent=2)[:2000])
except Exception as e: print('cost err',e)
try:
    posts=nm.analytics.get_social_posts(days=14, limit=20); print('\n-- posts --'); print(json.dumps(posts, indent=2)[:2000])
except Exception as e: print('posts err', e)
PY
